function addCompletedBookings(data){if(data.bookings?.some(b=>b.status==='Completed'))return;for(const l of data.legs.filter(x=>x.status==='Completed'&&x.actualStart&&x.actualEnd)){data.bookings.push({id:`BKG-${l.id}`,legId:l.id,programmeId:l.programmeId,methodId:l.methodId,start:l.actualStart,end:l.actualEnd,staffEnd:l.actualEnd,equipmentId:l.equipmentId,staffId:l.staffId,locked:true,status:'Completed',priority:data.programmes.find(p=>p.id===l.programmeId)?.priority||'Normal',dueDate:l.dueDate,lateHours:0});}}
async function init(){document.getElementById('versionText').textContent=`v${APP_VERSION}`;let loaded=await loadState();const usable=loaded?.meta&&Array.isArray(loaded.programmes)&&Array.isArray(loaded.legs);state=ensureStateShape(usable?loaded:createDemoData());const priorVersion=state.meta?.version||'';state.meta=state.meta||{};state.meta.version=APP_VERSION;if(usable&&priorVersion&&priorVersion!==APP_VERSION)state.audit.push(audit('Browser data schema upgraded','System',priorVersion,APP_VERSION));addCompletedBookings(state);recomputeRequirementStatuses(state);if(!(state.prototypeBookings||[]).length)schedulePrototypeBuilds(state);if(!state.settings.lastPlannerRun){const r=scheduleAll(state,{recordAudit:false});state=r.data;lastPlanDiagnostics=r.diagnostics;}await saveState(state);bindGlobal();render();if('serviceWorker'in navigator)navigator.serviceWorker.register('./service-worker.js').catch(()=>{});}
function bindGlobal(){nav.addEventListener('click',e=>{const b=e.target.closest('[data-route]');if(b)go(b.dataset.route)});document.querySelector('.brand').addEventListener('click',()=>go('dashboard'));document.getElementById('mobileNavBtn').addEventListener('click',()=>document.getElementById('sidebar').classList.toggle('open'));document.getElementById('modalClose').onclick=closeModal;modal.addEventListener('click',e=>{if(e.target===modal)closeModal()});document.getElementById('roleSelect').value=state.settings.role||'Lab Manager';document.getElementById('roleSelect').onchange=async e=>{state.settings.role=e.target.value;state.audit.push(audit('Role view changed','Demo UI','',e.target.value));await persist();const defaults={Technician:'execution','Test Engineer':'programmes',Planner:'planning','Lab Manager':'dashboard',Quality:'quality'};go(defaults[e.target.value]||'dashboard');};const s=document.getElementById('globalSearch');s.oninput=()=>search(s.value);s.onkeydown=e=>{if(e.key==='Escape'){s.value='';searchOverlay.classList.add('hidden')}};document.getElementById('importFile').onchange=importJSON;document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal();});}
function go(r){if(liveTimer){clearInterval(liveTimer);liveTimer=null;}route=r;document.getElementById('sidebar').classList.remove('open');for(const b of nav.querySelectorAll('button'))b.classList.toggle('active',b.dataset.route===r);render();window.scrollTo({top:0});}
async function persist(){await saveState(state);}
function audit(action,entity,prev,next){return{timestamp:new Date().toISOString(),actor:state.settings.actor||'Demo Lab Manager',action,entity,previousValue:String(prev??''),newValue:String(next??'')}}
function toast(msg){const t=document.getElementById('toast');t.textContent=msg;t.classList.remove('hidden');clearTimeout(t._timer);t._timer=setTimeout(()=>t.classList.add('hidden'),3200)}
function openModal(html){modalBody.innerHTML=html;modal.classList.remove('hidden');modalBody.querySelector('input,select,button')?.focus();}
function closeModal(){modal.classList.add('hidden');modalBody.innerHTML=''}
function pageHead(title,desc,actions=''){return `<div class="page-head"><div><h1>${title}</h1><p>${desc}</p></div><div class="actions">${actions}</div></div>`}
function kpiCard(label,value,sub=''){return `<div class="card kpi-card"><div class="label">${label}</div><div class="value">${value}</div><div class="sub">${sub}</div></div>`}
function drillKpiCard(label,value,sub,id){return `<button class="card kpi-card kpi-drill" data-act="kpi-drill" data-id="${id}"><div class="label">${label}</div><div class="value">${value}</div><div class="sub">${sub}</div><small>Tap for drivers and source records →</small></button>`}
function section(title,body,hint=''){return `<section class="card"><div class="section-title"><h2>${title}</h2>${hint?`<span class="hint">${hint}</span>`:''}</div>${body}</section>`}

function ensureStateShape(x){x.audit=x.audit||[];ensureOperationsState(x);ensurePrototypeState(x);x.testRuns=x.testRuns||[];x.issues=x.issues||[];x.disruptions=x.disruptions||[];x.specifications=x.specifications||[];x.documents=x.documents||[];x.testRequests=x.testRequests||[];x.devTasks=x.devTasks||[];x.settings=x.settings||{};x.settings.kpiPeriod=x.settings.kpiPeriod||{preset:'30d',start:dayISO(-30,0).slice(0,10),end:dayISO(0,23).slice(0,10)};x.settings.scenarioFocusProgramme=x.settings.scenarioFocusProgramme||x.programmes?.[0]?.id||'';x.settings.planningProject=x.settings.planningProject||'';x.settings.costProgramme=x.settings.costProgramme||'';x.settings.builderDraft=x.settings.builderDraft||null;x.settings.auditStandard=x.settings.auditStandard||'ISO17025';x.settings.auditRecord=x.settings.auditRecord||'';for(const p of x.programmes||[]){p.gateStatus=p.gateStatus||'Released';p.programmeManager=p.programmeManager||x.staff?.find(s=>s.name===p.owner)?.id||'';p.changeReason=p.changeReason||'';}for(const r of x.requirements||[]){const sp=x.specifications.find(s=>(s.linkedRequirementIds||[]).includes(r.id))||x.specifications.find(s=>s.programmeId===r.programmeId);r.specificationId=r.specificationId||sp?.id||'';r.acceptanceCriterion=r.acceptanceCriterion||({Environmental:'No loss of required function and all measured parameters remain within released limits after exposure.',Electrical:'Measured electrical parameters shall remain within released product limits.',Mechanical:'No structural damage and required functional performance shall be maintained.',Reliability:'No critical failure and degradation shall remain within the defined released limit.',EMC:'The DUT shall meet the applicable released immunity/emissions acceptance limits.',Functional:'All specified functions shall operate within the released performance limits.'}[r.category]||'Result shall meet the released specification acceptance limits.');r.validationIntent=r.validationIntent||'Demonstrate requirement compliance with objective test evidence.';}for(const sp of x.specifications||[]){sp.reviewChecks=sp.reviewChecks||{sourceTraceability:true,requirementsMapped:(sp.linkedRequirementIds||[]).length>0,acceptanceCriteria:!!sp.acceptanceBasis,sampleDefinition:Number(sp.qualityScore)>=70,methodRevision:(sp.linkedMethodIds||[]).length>0,releaseApproval:sp.status==='Released'};}for(const l of x.legs||[]){l.staffPolicy=l.staffPolicy||'Auto';l.preferredStaffId=l.preferredStaffId||null;l.sampleReadyDate=l.sampleReadyDate||l.requestedDate;}ensureCostFramework(x);ensureTimeLearningState(x);ensureLiveState(x);ensureWorkflowState(x);ensureAdvancedState(x);return x}
function periodRange(){const p=state.settings.kpiPeriod||{};return {start:p.start||dayISO(-30,0).slice(0,10),end:p.end||dayISO(0,23).slice(0,10),preset:p.preset||'custom'}}
function periodLabel(){const p=periodRange();return `${fmtDate(p.start)} – ${fmtDate(p.end)}`}
function isoDate(d){return new Date(d).toISOString().slice(0,10)}
function presetRange(v){const now=new Date(DEMO_NOW),d=new Date(DEMO_NOW);d.setUTCHours(0,0,0,0);if(v==='7d')return{start:isoDate(new Date(d.getTime()-6*86400000)),end:isoDate(d)};if(v==='30d')return{start:isoDate(new Date(d.getTime()-29*86400000)),end:isoDate(d)};if(v==='90d')return{start:isoDate(new Date(d.getTime()-89*86400000)),end:isoDate(d)};const mon=(x)=>{const z=new Date(x);const shift=(z.getUTCDay()+6)%7;z.setUTCDate(z.getUTCDate()-shift);return z};if(v==='thisWeek'){const a=mon(d);return{start:isoDate(a),end:isoDate(new Date(a.getTime()+6*86400000))}}if(v==='lastWeek'){const a=new Date(mon(d).getTime()-7*86400000);return{start:isoDate(a),end:isoDate(new Date(a.getTime()+6*86400000))}}if(v==='thisMonth'){return{start:`${now.getUTCFullYear()}-${String(now.getUTCMonth()+1).padStart(2,'0')}-01`,end:isoDate(new Date(Date.UTC(now.getUTCFullYear(),now.getUTCMonth()+1,0)))}}if(v==='lastMonth'){const y=now.getUTCMonth()===0?now.getUTCFullYear()-1:now.getUTCFullYear(),m=now.getUTCMonth()===0?11:now.getUTCMonth()-1;return{start:`${y}-${String(m+1).padStart(2,'0')}-01`,end:isoDate(new Date(Date.UTC(y,m+1,0)))}}return periodRange()}
function weekValueFor(date){const d=new Date(Date.UTC(date.getUTCFullYear(),date.getUTCMonth(),date.getUTCDate()));d.setUTCDate(d.getUTCDate()+4-(d.getUTCDay()||7));const y=new Date(Date.UTC(d.getUTCFullYear(),0,1));const w=Math.ceil((((d-y)/86400000)+1)/7);return `${d.getUTCFullYear()}-W${String(w).padStart(2,'0')}`}
function periodControls(){const p=periodRange(),now=new Date(DEMO_NOW);return `<div class="period-bar card"><div class="period-title"><strong>KPI period</strong><span>${periodLabel()}</span></div><label>Preset<select id="periodPreset"><option value="custom" ${p.preset==='custom'?'selected':''}>Custom</option>${[['thisWeek','This week'],['lastWeek','Last week'],['thisMonth','This month'],['lastMonth','Last month'],['7d','Last 7 days'],['30d','Last 30 days'],['90d','Last 90 days']].map(([v,l])=>`<option value="${v}" ${p.preset===v?'selected':''}>${l}</option>`).join('')}</select></label><label>Week<input id="periodWeek" type="week" value="${weekValueFor(now)}"></label><label>Month<input id="periodMonth" type="month" value="${now.getUTCFullYear()}-${String(now.getUTCMonth()+1).padStart(2,'0')}"></label><label>From<input id="periodStart" type="date" value="${p.start}"></label><label>To<input id="periodEnd" type="date" value="${p.end}"></label></div>`}
async function wirePeriodControls(){const preset=document.getElementById('periodPreset'),week=document.getElementById('periodWeek'),month=document.getElementById('periodMonth'),start=document.getElementById('periodStart'),end=document.getElementById('periodEnd');if(!preset)return;const set=async(p)=>{state.settings.kpiPeriod=p;await persist();render()};preset.onchange=()=>{const r=presetRange(preset.value);set({...r,preset:preset.value})};week.onchange=()=>{const m=/^(\d{4})-W(\d{2})$/.exec(week.value);if(!m)return;const y=+m[1],w=+m[2],jan4=new Date(Date.UTC(y,0,4)),mon=new Date(jan4.getTime()-((jan4.getUTCDay()+6)%7)*86400000+(w-1)*7*86400000);set({preset:'custom',start:isoDate(mon),end:isoDate(new Date(mon.getTime()+6*86400000))})};month.onchange=()=>{const [y,m]=month.value.split('-').map(Number);if(!y||!m)return;set({preset:'custom',start:`${y}-${String(m).padStart(2,'0')}-01`,end:isoDate(new Date(Date.UTC(y,m,0)))})};for(const el of [start,end])el.onchange=()=>{if(!start.value||!end.value)return;if(new Date(end.value)<new Date(start.value)){toast('KPI period end must be on or after the start date.');return}set({preset:'custom',start:start.value,end:end.value})}}
function trendViz(tr){const rows=tr.rows||[];if(!rows.length)return'<div class="empty">No period data.</div>';const W=680,H=230,pad=34,max=Math.max(1,...rows.flatMap(r=>[r.completed,r.issues]));const pts=(key)=>rows.map((r,i)=>`${pad+(rows.length===1?0:i*(W-pad*2)/(rows.length-1))},${H-pad-(r[key]/max)*(H-pad*2)}`).join(' ');const labels=rows.filter((_,i)=>i===0||i===rows.length-1||i===Math.floor(rows.length/2)).map((r)=>{const i=rows.indexOf(r),x=pad+(rows.length===1?0:i*(W-pad*2)/(rows.length-1));return`<text x="${x}" y="${H-9}" text-anchor="middle">${new Date(r.date).toLocaleDateString(undefined,{month:'short',day:'numeric'})}</text>`}).join('');return `<div class="chart-legend"><span><i class="legend-dot teal"></i>Tests completed</span><span><i class="legend-dot amber"></i>Issues</span><span>${tr.mode} buckets</span></div><svg class="chart-svg" viewBox="0 0 ${W} ${H}" role="img" aria-label="Tests completed and issues over selected period"><line x1="${pad}" y1="${H-pad}" x2="${W-pad}" y2="${H-pad}" class="axis"/><polyline points="${pts('completed')}" class="line teal"/><polyline points="${pts('issues')}" class="line amber"/>${rows.map((r,i)=>{const x=pad+(rows.length===1?0:i*(W-pad*2)/(rows.length-1)),y1=H-pad-(r.completed/max)*(H-pad*2),y2=H-pad-(r.issues/max)*(H-pad*2);return`<circle cx="${x}" cy="${y1}" r="3.5" class="point teal"><title>${r.date}: ${r.completed} tests completed</title></circle><circle cx="${x}" cy="${y2}" r="3.5" class="point amber"><title>${r.date}: ${r.issues} issues</title></circle>`}).join('')}${labels}</svg>`}
function horizontalViz(items,valueKey='count',suffix=''){if(!items?.length)return'<div class="empty">No data in this period.</div>';const max=Math.max(1,...items.map(x=>Number(x[valueKey])||0));return `<div class="viz-bars">${items.map((x,i)=>`<div class="viz-bar"><div><strong>${esc(x.name||x.label||x.category)}</strong><span>${Number(x[valueKey])||0}${suffix}${x.delayHours!=null?` · ${Math.round(x.delayHours)}h delay`:''}</span></div><div class="viz-track"><i style="width:${Math.max(2,(Number(x[valueKey])||0)/max*100)}%"></i></div></div>`).join('')}</div>`}
function rootCauseDonut(rows){if(!rows?.length)return'<div class="empty">No issues in this period.</div>';const total=rows.reduce((a,x)=>a+x.count,0),palette=['#0f897f','#bd7c13','#b63b45','#3268b8','#7651a8','#61777c'];let cur=0;const seg=rows.slice(0,6).map((x,i)=>{const a=cur,b=cur+x.count/total*100;cur=b;return`${palette[i]} ${a}% ${b}%`}).join(',');return `<div class="donut-wrap"><div class="donut" style="background:conic-gradient(${seg})"><div><strong>${total}</strong><span>issues</span></div></div><div class="donut-legend">${rows.slice(0,6).map((x,i)=>`<div><i style="background:${palette[i]}"></i><span>${esc(x.name)}</span><strong>${x.count} · ${Math.round(x.count/total*100)}%</strong></div>`).join('')}</div></div>`}
function outcomeViz(pm){const total=Math.max(1,pm.completed),pass=pm.pass/total*100,fail=pm.failed/total*100,rework=pm.rework/total*100;return `<div class="outcome-stack"><div class="outcome-bar"><span class="pass" style="width:${pass}%"></span><span class="rework" style="width:${rework}%"></span><span class="fail" style="width:${fail}%"></span></div><div class="chart-legend"><span>PASS ${pm.pass} (${Math.round(pass)}%)</span><span>REWORK ${pm.rework} (${Math.round(rework)}%)</span><span>FAIL ${pm.failed} (${Math.round(fail)}%)</span></div></div>`}
function priorityMaps(){const ps=state.programmes,focus=state.settings.scenarioFocusProgramme||ps[0]?.id;const due={};for(const p of ps){const d=(new Date(p.dueDate)-DEMO_NOW)/86400000;due[p.id]=d<=21?'Critical':d<=35?'High':d<=50?'Normal':'Low'}const sorted=[...ps].sort((a,b)=>b.businessPriority-a.businessPriority),biz={};sorted.forEach((p,i)=>biz[p.id]=i<2?'Critical':i<5?'High':i<8?'Normal':'Low');const foc={};for(const p of ps)foc[p.id]=p.id===focus?'Critical':p.priority==='Critical'?'High':p.priority==='High'?'Normal':'Low';return[{id:'baseline',name:'Baseline priorities',map:null,desc:'Current project priorities'},{id:'due',name:'Due-date protection',map:due,desc:'Near-term due dates receive highest priority'},{id:'business',name:'Business-value first',map:biz,desc:'Highest business-priority scores receive capacity first'},{id:'focus',name:`Focus ${focus}`,map:foc,desc:'Selected project becomes Critical; other work yields capacity'}]}
function scenarioComparison(){return priorityMaps().map(sc=>{const scenario=sc.map?{type:'priority_mix',priorityMap:sc.map,label:sc.name}:null;const r=scheduleAll(state,{scenario,recordAudit:false}),d=r.data,late=d.bookings.filter(b=>b.lateHours>0),atRisk=d.programmes.filter(p=>['Late','At Risk','Blocked'].includes(p.scheduleRisk)).length,onTime=d.programmes.filter(p=>p.forecastCompletion&&new Date(p.forecastCompletion)<=new Date(p.dueDate)).length,totalLate=Math.round(late.reduce((a,b)=>a+b.lateHours,0)/24*10)/10;return{...sc,atRisk,onTime,late:late.length,totalLate,moved:r.diagnostics.moved.length,unscheduled:r.diagnostics.unscheduled.length}})}
function scenarioCards(){const rows=scenarioComparison(),max=Math.max(1,...rows.map(x=>x.totalLate));return `<div class="scenario-grid">${rows.map(x=>`<article class="scenario-card ${state.settings.scenario?.label===x.name?'active':''}"><div class="scenario-top"><div><strong>${esc(x.name)}</strong><small>${esc(x.desc)}</small></div>${x.id!=='baseline'?`<button class="btn small" data-act="apply-priority-scenario" data-strategy="${x.id}">Apply</button>`:''}</div><div class="scenario-numbers"><span><b>${x.onTime}</b> on time</span><span><b>${x.atRisk}</b> at risk</span><span><b>${x.totalLate}</b> late days</span></div><div class="viz-track"><i style="width:${Math.max(2,x.totalLate/max*100)}%"></i></div><small>${x.moved} bookings move · ${x.unscheduled} unscheduled</small></article>`).join('')}</div>`}

function methodLessons(methodId){
 const runs=(state.testRuns||[]).filter(r=>r.methodId===methodId),legIds=new Set(state.legs.filter(l=>l.methodId===methodId).map(l=>l.id)),runIds=new Set(runs.map(r=>r.id));
 const issues=(state.issues||[]).filter(i=>runIds.has(i.testRunId)||legIds.has(i.legId));const counts={};for(const i of issues)counts[i.issueType]=(counts[i.issueType]||0)+1;
 const top=Object.entries(counts).sort((a,b)=>b[1]-a[1])[0];const root={};for(const i of issues)root[i.rootCause]=(root[i.rootCause]||0)+1;const topRoot=Object.entries(root).sort((a,b)=>b[1]-a[1])[0];
 const T=methodTimeMetrics(state,methodId),qualified=state.staff.filter(s=>s.qualifications?.some(q=>q.methodId===methodId&&['Independent','Reviewer','Trainer/Expert'].includes(q.level)&&new Date(q.expires)>DEMO_NOW));
 const sources=issues.slice().sort((a,b)=>new Date(b.reportedAt)-new Date(a.reportedAt)).map(i=>{const run=state.testRuns.find(r=>r.id===i.testRunId),leg=state.legs.find(l=>l.id===(i.legId||run?.legId)),p=state.programmes.find(p=>p.id===(i.programmeId||run?.programmeId)),st=state.staff.find(s=>s.id===run?.staffId),eq=state.equipment.find(e=>e.id===run?.equipmentId);return{issue:i,run,leg,programme:p,staff:st,equipment:eq}});
 const rec=issues.slice().sort((a,b)=>(b.delayHours||0)-(a.delayHours||0))[0]?.lesson||'No recurrent issue signal; use the released method and standard pre-test readiness checks.';
 return {runs:runs.length,issues:issues.length,delayHours:Math.round(issues.reduce((a,i)=>a+(Number(i.delayHours)||0),0)),topIssue:top?.[0]||'No recurring issue',topCount:top?.[1]||0,topRoot:topRoot?.[0]||'None',variance:T.durationVariancePct,durationVariance:T.durationVariancePct,productivePct:T.productivePct,queuePct:T.queuePct,firstTimeRightPct:T.firstTimeRightPct,learned:T.learned,confidence:T.confidence,qualified:qualified.length,qualifiedNames:qualified.map(x=>x.name),recommendation:rec,sources};
}
function programmeReadiness(pid){const p=state.programmes.find(x=>x.id===pid),legs=state.legs.filter(l=>l.programmeId===pid),specs=state.specifications.filter(s=>s.programmeId===pid),checks=[];checks.push({name:'Programme gate',ok:p?.gateStatus==='Released',detail:p?.gateStatus||'Missing'});checks.push({name:'Released specification',ok:specs.some(s=>s.status==='Released'),detail:specs.some(s=>s.status==='Released')?'Released test basis available':'No released specification'});checks.push({name:'Methods ready',ok:legs.every(l=>{const m=state.methods.find(x=>x.id===l.methodId);return m?.active||l.developmentTaskId}),detail:`${legs.filter(l=>!state.methods.find(m=>m.id===l.methodId)?.active).length} method(s) require development/release`});checks.push({name:'Sample readiness',ok:legs.every(l=>!l.sampleReadyDate||new Date(l.sampleReadyDate)<=new Date(l.dueDate)),detail:`${legs.filter(l=>l.sampleReadyDate&&new Date(l.sampleReadyDate)>DEMO_NOW).length} future sample-ready dates`});checks.push({name:'Competency coverage',ok:legs.every(l=>methodLessons(l.methodId).qualified>0),detail:`${legs.filter(l=>methodLessons(l.methodId).qualified===0).length} uncovered method(s)`});return {checks,score:Math.round(checks.filter(x=>x.ok).length/Math.max(1,checks.length)*100)};}

function specificationForRequirement(r){return state.specifications.find(s=>s.id===r.specificationId)||state.specifications.find(s=>(s.linkedRequirementIds||[]).includes(r.id))||state.specifications.find(s=>s.programmeId===r.programmeId)||null}
function recommendedMethodForRequirement(r){const exact=state.methods.find(m=>m.active&&m.category===r.category);if(exact)return exact;const aliases={Environmental:['Temperature','Humidity','Environmental'],Mechanical:['Mechanical','Vibration','Shock','Durability'],Electrical:['Electrical'],Reliability:['Reliability','Durability'],EMC:['EMC'],Functional:['Functional','Software/Firmware']};const cats=aliases[r.category]||[r.category];return state.methods.find(m=>m.active&&cats.includes(m.category))||state.methods.find(m=>m.active)||null}
function requirementOps(r){const p=state.programmes.find(x=>x.id===r.programmeId),sp=specificationForRequirement(r),legs=state.legs.filter(l=>(l.requirementIds||[]).includes(r.id)),methods=legs.map(l=>state.methods.find(m=>m.id===l.methodId)).filter(Boolean),dev=legs.filter(l=>l.developmentTaskId&&!state.devTasks.find(d=>d.id===l.developmentTaskId)?.completeDate),results=state.results.filter(x=>legs.some(l=>l.id===x.legId)),suggested=recommendedMethodForRequirement(r),est=legs.length?legs.reduce((a,l)=>a+estimateLegCost(state,l).total,0):(suggested?methodCost(state,suggested.id,8)?.total||0:0);let action='Covered';if(!sp||sp.status!=='Released')action='Specification gate';else if(!legs.length)action='Create test demand';else if(dev.length)action='Method development';else if(legs.some(l=>l.blockingReason))action='Resolve blocker';else if(!results.length)action='Execute / evidence';else if(r.status==='Failed')action='Failure disposition';else if(r.status!=='Verified')action='Complete verification';return {p,sp,legs,methods,dev,results,suggested,estimatedCost:est,action}}
function specificationReadiness(sp){const reqs=state.requirements.filter(r=>r.specificationId===sp.id||(!r.specificationId&&(sp.linkedRequirementIds||[]).includes(r.id))),legs=state.legs.filter(l=>reqs.some(r=>(l.requirementIds||[]).includes(r.id))),methodIds=[...new Set([...(sp.linkedMethodIds||[]),...legs.map(l=>l.methodId)])],methods=methodIds.map(id=>state.methods.find(m=>m.id===id)).filter(Boolean),releasedMethods=methods.filter(m=>m.active).length,accept=reqs.filter(r=>r.acceptanceCriterion?.trim()).length,issues=(state.issues||[]).filter(i=>i.specificationId===sp.id|| (i.programmeId===sp.programmeId&&i.rootCause==='Bad Specification')),activeLegs=legs.filter(l=>l.status!=='Completed').length,blocked=legs.filter(l=>l.blockingReason&&/specification|release/i.test(l.blockingReason)).length,reqPct=pct(reqs.length,Math.max(1,state.requirements.filter(r=>r.programmeId===sp.programmeId).length)),methodPct=pct(releasedMethods,Math.max(1,methods.length)),acceptPct=pct(accept,Math.max(1,reqs.length)),score=Math.round((Number(sp.qualityScore||0)*.45)+(reqPct*.2)+(methodPct*.2)+(acceptPct*.15));return {reqs,legs,methods,releasedMethods,accept,issues,activeLegs,blocked,reqPct,methodPct,acceptPct,score}}
function requirementAttentionScore(r){const o=requirementOps(r);return (r.criticality==='Critical'?40:r.criticality==='High'?25:r.criticality==='Medium'?10:0)+(r.status==='Failed'?45:r.status==='Not Covered'?35:r.status==='Blocked'?30:r.status==='Partially Verified'?15:r.status==='Planned'?10:0)+(o.sp?.status!=='Released'?15:0)+(o.dev.length?10:0)}
function costMixViz(parts){parts=parts||{};const rows=Object.entries(parts).filter(([k])=>['labour','equipment','consumables','external','development','overhead','contingency'].includes(k)).map(([name,value])=>({name:name[0].toUpperCase()+name.slice(1),value:Number(value)||0})).filter(x=>x.value>0);const total=Math.max(1,rows.reduce((a,x)=>a+x.value,0));return `<div class="cost-mix">${rows.map(x=>`<div class="cost-mix-row"><div><strong>${x.name}</strong><span>${currency(state,x.value,true)} · ${Math.round(x.value/total*100)}%</span></div><div class="viz-track"><i style="width:${x.value/total*100}%"></i></div></div>`).join('')}</div>`}
function renderCosts(){const P=portfolioCost(state),pid=state.settings.costProgramme||'',pc=pid?programmeCost(state,pid):null,p=pid?state.programmes.find(x=>x.id===pid):null,over=P.programmes.filter(x=>x.variance>0).length,topMethods=state.methods.map(m=>({m,c:methodCost(state,m.id,8)})).filter(x=>x.c).sort((a,b)=>b.c.total-a.c.total).slice(0,10),ranked=P.programmes.slice().sort((a,b)=>b.forecast-a.forecast);const scopeBar=`<div class="project-plan-bar card"><label>Cost view<select id="costProgramme"><option value="">Portfolio / all programmes</option>${state.programmes.map(x=>`<option value="${x.id}" ${pid===x.id?'selected':''}>${x.id} · ${esc(x.project)}</option>`).join('')}</select></label><div class="project-plan-meta">${pid?`<strong>${p.id} · ${esc(p.project)}</strong><span>${esc(p.product)} · ${p.priority} · ${p.gateStatus}</span>`:'<strong>Portfolio financial control</strong><span>Budget, estimate, actual-to-date and forecast from the same test-leg resource model used by planning</span>'}</div><div class="actions">${pid?`<button class="btn" data-act="edit-cost-budget" data-id="${pid}">€ Budget / target</button>`:''}<button class="btn" data-act="export-cost-csv">⇩ Cost CSV</button><button class="btn primary" data-act="cost-settings">⚙ Rate Card</button></div></div>`;if(pid){const legRows=pc.legs.slice().sort((a,b)=>a.leg.sequence-b.leg.sequence),mix=pc.estimated,top=legRows.slice().sort((a,b)=>b.estimate.total-a.estimate.total)[0],costPerDut=pc.forecast/Math.max(1,state.duts.filter(d=>d.programmeId===pid).length);return pageHead('Test Cost & Finance',`Programme cost control for ${p.project} · costs recalculate from the current plan and resource assignment`)+scopeBar+`<div class="grid kpi visual-kpis">${kpiCard('Programme budget',currency(state,pc.budget,true),'Editable project financial guardrail')}${kpiCard('Forecast at completion',currency(state,pc.forecast,true),`${pc.variance>=0?'+':''}${pc.variancePct}% vs budget`)}${kpiCard('Actual to date',currency(state,pc.actualToDate,true),'Completed test execution')}${kpiCard('Estimate to complete',currency(state,pc.remaining,true),'Open and planned test legs')}${kpiCard('Cost / DUT',currency(state,costPerDut,true),`${state.duts.filter(d=>d.programmeId===pid).length} DUTs in programme`)}${kpiCard('Highest-cost leg',top?currency(state,top.estimate.total,true):'—',top?`${top.leg.id} · ${top.leg.name}`:'No test legs')}</div><div class="grid section-grid equal">${section('Programme cost composition',costMixViz(mix),'Labour, equipment, consumables, external, development, overhead and contingency')}${section('Financial control position',`<div class="finance-bars"><div class="bar-row"><div class="bar-head"><strong>Budget</strong><span>${currency(state,pc.budget,true)}</span></div><div class="progress"><span style="width:100%"></span></div></div><div class="bar-row"><div class="bar-head"><strong>Forecast</strong><span>${currency(state,pc.forecast,true)}</span></div><div class="progress"><span style="width:${Math.min(100,pc.budget?pc.forecast/pc.budget*100:100)}%"></span></div></div><div class="callout ${pc.variance>0?'warning':''}"><strong>${pc.variance>0?'Management action':'Within budget'}:</strong> ${pc.variance>0?`forecast exceeds budget by ${currency(state,pc.variance,true)}. Focus first on high-cost open legs and method-development work.`:`current forecast is ${currency(state,Math.abs(pc.variance),true)} inside budget.`}</div></div>`,'Forecast = completed actuals + estimate to complete')}</div><div style="margin-top:14px">${section('Test-leg cost control',`<div class="table-wrap"><table><thead><tr><th>Seq</th><th>Leg / Method</th><th>Status</th><th>Labour</th><th>Equipment</th><th>Consumables / External</th><th>Development</th><th>Overhead / Risk</th><th>Total</th><th>Plan</th></tr></thead><tbody>${legRows.map(x=>`<tr><td>${x.leg.sequence}</td><td><span class="link mono" data-entity="leg" data-id="${x.leg.id}">${x.leg.id}</span><div><strong>${esc(x.leg.name)}</strong></div><div class="small muted">${x.leg.methodId}</div></td><td>${pill(x.leg.status)}</td><td>${currency(state,x.estimate.labour,true)}</td><td>${currency(state,x.estimate.equipment,true)}</td><td>${currency(state,x.estimate.consumables+x.estimate.external,true)}</td><td>${currency(state,x.estimate.development,true)}</td><td>${currency(state,x.estimate.overhead+x.estimate.contingency,true)}</td><td><strong>${currency(state,x.estimate.total,true)}</strong>${x.actual?`<div class="small muted">actual ${currency(state,x.actual.total,true)}</div>`:''}</td><td>${fmtDate(x.leg.plannedStart,true)}</td></tr>`).join('')}</tbody></table></div>`,'Every row uses the canonical cost engine; changing staff/equipment or plan dates updates the forecast')}</div><div class="grid section-grid equal" style="margin-top:14px">${section('Cost reduction opportunities',`<div class="list">${legRows.slice().sort((a,b)=>b.estimate.total-a.estimate.total).slice(0,6).map((x,i)=>{const m=state.methods.find(mm=>mm.id===x.leg.methodId),L=methodLessons(x.leg.methodId);return`<div class="list-row"><div><strong>${i+1}. ${x.leg.id} · ${esc(x.leg.name)}</strong><small>${currency(state,x.estimate.total,true)} · ${x.estimate.wallHours}h equipment · ${x.estimate.staffHours}h attended staff · ${L.issues} historical issues</small></div>${pill(m?.active?'Standard':'Development')}</div>`}).join('')}</div>`,'Prioritised by forecast leg cost')}${section('Rate-card assumptions',costRateTable(),'Edit the rate card to see all estimates recalculate immediately')}</div>`}return pageHead('Test Cost & Finance','Portfolio budget, cost drivers and programme drill-down tied directly to the operational test plan')+scopeBar+`<div class="grid kpi visual-kpis">${kpiCard('Portfolio budget',currency(state,P.totalBudget,true),'Current programme budgets')}${kpiCard('Forecast at completion',currency(state,P.totalForecast,true),`${over} programme(s) forecast over budget`)}${kpiCard('Forecast variance',currency(state,P.variance,true),P.variance>0?'Above budget':'Within portfolio budget')}${kpiCard('Development cost',currency(state,P.development,true),'Method / fixture development')}${kpiCard('Equipment cost',currency(state,P.equipment,true),'Planned laboratory occupancy')}${kpiCard('Labour cost',currency(state,P.labour,true),'Qualified attended resource')}</div><div class="grid section-grid equal">${section('Budget vs forecast by programme',`<div class="list">${ranked.map(x=>{const max=Math.max(x.budget,x.forecast,1);return`<div class="cost-compare"><div class="bar-head"><strong>${x.programmeId} · ${esc(x.programme.project)}</strong><span>${currency(state,x.forecast,true)} / ${currency(state,x.budget,true)}</span></div><div class="dual-bars"><i class="budget" style="width:${x.budget/max*100}%"></i><i class="forecast" style="width:${x.forecast/max*100}%"></i></div><small class="muted">${x.variance>0?`Over by ${currency(state,x.variance,true)}`:`Headroom ${currency(state,Math.abs(x.variance),true)}`}</small></div>`}).join('')}</div>`,'Select a programme above for leg-level financial control')}${section('Portfolio cost composition',costMixViz(P.breakdown),'Forecast planning cost drivers')}</div><div class="grid section-grid equal" style="margin-top:14px">${section('Programme cost control',`<div class="table-wrap"><table><thead><tr><th>Programme</th><th>Budget</th><th>Estimate</th><th>Actual</th><th>Forecast</th><th>Variance</th><th>Action</th></tr></thead><tbody>${ranked.map(x=>`<tr><td><span class="link mono" data-entity="programme" data-id="${x.programmeId}">${x.programmeId}</span><div class="small muted">${esc(x.programme.project)}</div></td><td>${currency(state,x.budget,true)}</td><td>${currency(state,x.estimated.total,true)}</td><td>${currency(state,x.actualToDate,true)}</td><td><strong>${currency(state,x.forecast,true)}</strong></td><td>${pill(`${x.variance>=0?'+':''}${x.variancePct}%`)}</td><td><button class="btn small" data-act="cost-programme" data-id="${x.programmeId}">Open</button></td></tr>`).join('')}</tbody></table></div>`,'Open a programme to inspect every test-leg cost')}${section('Highest-cost standard methods',horizontalViz(topMethods.map(x=>({name:`${x.m.id} · ${x.m.name}`,count:Math.round(x.c.total)})),'count',' EUR'),'Typical 8-DUT leg using current rate card')}</div><div style="margin-top:14px">${section('Cost framework rate card',costRateTable(),'Editable rates and overhead assumptions are persisted browser-locally')}</div>`}
function costRateTable(){const c=state.settings.costFramework;return `<div class="table-wrap"><table><thead><tr><th>Resource</th><th>Type / Role</th><th>Rate</th></tr></thead><tbody>${state.staff.slice(0,10).map(s=>`<tr><td>${esc(s.name)}</td><td>${esc(s.role)}</td><td>${currency(state,s.costRatePerHour)}/h</td></tr>`).join('')}${state.equipment.slice(0,10).map(e=>`<tr><td>${e.id}</td><td>${esc(e.type)}</td><td>${currency(state,e.chargeRatePerHour)}/h</td></tr>`).join('')}<tr><td>Overhead</td><td>Applied to direct cost</td><td>${c.overheadPct}%</td></tr><tr><td>Planning contingency</td><td>Open-work risk allowance</td><td>${c.contingencyPct}%</td></tr></tbody></table></div>`}

function defaultBuilderDraft(){return {project:'Project Aurora',customer:'Demo Customer',product:'Sensor Platform Z1',revision:'R1.0',priority:'Normal',businessPriority:75,dueDate:dayISO(45,17).slice(0,10),dutCount:20,budget:35000,requirementText:'Product shall demonstrate released performance and durability requirements across the complete validation sequence.',legs:[],notes:'Built from LabOS Test Library with automatic lessons-learned review.'};}
function getBuilderDraft(){if(!state.settings.builderDraft)state.settings.builderDraft=defaultBuilderDraft();const d=state.settings.builderDraft;d.legs=d.legs||[];if(!d.legs.length&&d.selected&&Object.keys(d.selected).length){let seq=0;for(const [methodId,cfg] of Object.entries(d.selected)){d.legs.push({id:`BL-${Date.now()}-${seq++}`,kind:'existing',methodId,legName:state.methods.find(m=>m.id===methodId)?.name||methodId,dutCount:Number(d.dutCount)||8,populationMode:'Continue',dependencyMode:seq===1?'Start':'Sequential',staffId:cfg.staffId||'',staffPolicy:cfg.staffPolicy||'Auto',sampleReadyOffset:0});}d.selected={};}return d;}
function builderSelectedItems(){const d=getBuilderDraft();return (d.legs||[]).map((cfg,i)=>{if(cfg.kind==='custom'){return{kind:'custom',key:cfg.id,method:{id:cfg.tempId||`NEW-DRAFT-${i+1}`,name:cfg.name||cfg.legName||'New method',category:cfg.category||'Other',equipmentType:cfg.equipmentType||state.equipment[0]?.type,requiredSkills:[cfg.skill||state.staff[0]?.skills?.[0]||'General'],executionHours:Number(cfg.executionHours)||8,setupHours:Number(cfg.setupHours)||4,teardownHours:Number(cfg.teardownHours)||2,analysisHours:Number(cfg.analysisHours)||4,active:false,dutCapacity:Number(cfg.dutCapacity)||8},cfg};}const m=state.methods.find(x=>x.id===cfg.methodId);return m?{kind:'existing',key:cfg.id,method:m,cfg}:null}).filter(Boolean);}
function builderSummary(){const d=getBuilderDraft(),items=builderSelectedItems(),existing=items.filter(x=>x.kind==='existing').length,newCount=items.length-existing;let cost=0,devDays=0,qualificationGaps=0;for(const x of items){const count=Math.max(1,Number(x.cfg.dutCount)||Number(d.dutCount)||1);if(x.kind==='existing'){const tempLeg={id:'BUILDER-COST',methodId:x.method.id,dutIds:Array.from({length:count},(_,i)=>`D${i+1}`),staffId:x.cfg.staffId||null};cost+=estimateLegCost(state,tempLeg).total;}else{const fakeMethod={...x.method,staffing:1,unattended:true,continuousStaffing:false,avgActualFactor:1,consumablesPerDut:8,fixedConsumables:20,externalCost:0,costRiskPct:12};const temp=cloneData(state);temp.methods.push(fakeMethod);temp.devTasks.push({id:'BUILDER-DEV',estimatedEngineeringHours:Number(x.cfg.engineeringHours)||40,estimatedTechnicianHours:Number(x.cfg.technicianHours)||16,fixtureCost:Number(x.cfg.fixtureCost)||750,externalCost:0});cost+=estimateLegCost(temp,{id:'BUILDER-LEG',methodId:fakeMethod.id,dutIds:Array.from({length:count},(_,i)=>`D${i+1}`),developmentTaskId:'BUILDER-DEV'}).total;devDays=Math.max(devDays,Number(x.cfg.devDays)||7);}if(x.cfg.staffId&&x.cfg.staffPolicy==='Required'&&x.kind==='existing'){const q=state.staff.find(s=>s.id===x.cfg.staffId)?.qualifications?.some(q=>q.methodId===x.method.id&&['Independent','Reviewer','Trainer/Expert'].includes(q.level));if(!q)qualificationGaps++;}}return {items,existing,newCount,cost:Math.round(cost),devDays,qualificationGaps,totalDuts:Number(d.dutCount)||1};}
function renderProjectPlanRows(pid){
 if(!pid){
  const rows=state.programmes.map(p=>{const ls=state.legs.filter(l=>l.programmeId===p.id),open=ls.filter(l=>!['Completed','Cancelled','Failed'].includes(l.status)).length,blocked=ls.filter(l=>l.blockingReason).length,pc=programmeCost(state,p.id),R=programmeReadiness(p.id);return {p,open,blocked,pc,R}}).sort((a,b)=>new Date(a.p.dueDate)-new Date(b.p.dueDate));
  return `<div class="table-wrap"><table><thead><tr><th>Project / Programme</th><th>Priority</th><th>Gate</th><th>Due / Forecast</th><th>Open / Blocked</th><th>Readiness</th><th>Forecast cost</th><th>Risk</th><th>Action</th></tr></thead><tbody>${rows.map(({p,open,blocked,pc,R})=>`<tr><td><strong>${esc(p.project)}</strong><div class="small muted">${p.id} · ${esc(p.product)}</div></td><td>${pill(p.priority)}<div class="small muted">business ${p.businessPriority}</div></td><td>${pill(p.gateStatus)}</td><td>${fmtDate(p.dueDate)}<div class="small muted">forecast ${fmtDate(p.forecastCompletion)}</div></td><td><strong>${open}</strong><div class="small muted">${blocked} blocked</div></td><td><strong>${R.score}%</strong><div class="progress"><span style="width:${R.score}%"></span></div></td><td>${currency(state,pc.forecast,true)}<div class="small muted">budget ${currency(state,pc.budget,true)}</div></td><td>${pill(p.scheduleRisk||p.status)}</td><td><button class="btn small primary" data-act="open-project-plan" data-id="${p.id}">Open project plan</button></td></tr>`).join('')}</tbody></table></div>`;
 }
 const p=state.programmes.find(x=>x.id===pid);if(!p)return '<div class="empty">Project not found.</div>';
 const rows=state.legs.filter(l=>l.programmeId===pid).sort((a,b)=>a.sequence-b.sequence);
 return `<div class="table-wrap"><table><thead><tr><th>Seq</th><th>Test leg / Method</th><th>Method state</th><th>Sample ready</th><th>Required by</th><th>Planned resources</th><th>Staff policy</th><th>Forecast cost</th><th>Status / Constraint</th><th>Action</th></tr></thead><tbody>${rows.map(l=>{const m=state.methods.find(x=>x.id===l.methodId),b=state.bookings.find(x=>x.legId===l.id),c=estimateLegCost(state,l),dev=l.developmentTaskId?state.devTasks.find(x=>x.id===l.developmentTaskId):null,st=state.staff.find(x=>x.id===l.staffId),eq=state.equipment.find(x=>x.id===l.equipmentId);return `<tr><td>${l.sequence}</td><td><span class="link mono" data-entity="leg" data-id="${l.id}">${l.id}</span><div><strong>${esc(l.name)}</strong></div><div class="small muted">${m?.id||l.methodId} · ${m?.category||'—'}</div></td><td>${pill(m?.active?'Released':'Development')}<div class="small muted">${dev&&!dev.completeDate?`${dev.id} due ${fmtDate(dev.dueDate)}`:m?.revision?`Rev ${m.revision}`:'—'}</div></td><td>${fmtDate(l.sampleReadyDate,true)}${new Date(l.sampleReadyDate||0)>DEMO_NOW?'<div class="small muted">future constraint</div>':''}</td><td>${fmtDate(l.dueDate,true)}</td><td>${b?`<strong>${eq?.id||b.equipmentId}</strong><div class="small muted">${esc(st?.name||b.staffId)} · ${fmtDate(b.start,true)}</div>${b.locked?'<span class="pill blue">Locked</span>':''}`:'<span class="muted">Unscheduled</span>'}</td><td>${pill(l.staffPolicy||'Auto')}<div class="small muted">${l.preferredStaffId?esc(state.staff.find(s=>s.id===l.preferredStaffId)?.name||l.preferredStaffId):'scheduler chooses'}</div></td><td><strong>${currency(state,c.total,true)}</strong><div class="small muted">${Math.round(c.wallHours*10)/10}h wall time</div></td><td>${pill(l.status)}${l.blockingReason?`<div class="small danger-text">${esc(l.blockingReason)}</div>`:(l.planExplanation?.[0]?`<div class="small muted">${esc(l.planExplanation[0]).slice(0,120)}</div>`:'')}</td><td><button class="btn small" data-act="edit-project-leg" data-id="${l.id}">Edit inputs</button><button class="btn small" data-act="log-delay" data-id="${l.id}" data-programme="${l.programmeId}">Log delay</button>${b?`<button class="btn small" data-booking="${b.id}">Manual booking</button>`:''}</td></tr>`}).join('')||'<tr><td colspan="10"><div class="empty">No test legs in this project.</div></td></tr>'}</tbody></table></div>`;
}

function projectControlsModal(id){
 const p=state.programmes.find(x=>x.id===id);if(!p)return;
 const pc=programmeCost(state,id),R=programmeReadiness(id);
 openModal(`<h2>${id} · Project Planning Controls</h2><p class="small muted">Changes here are project-level planning inputs. Saving them immediately rebuilds the shared laboratory schedule so displacement of other projects remains visible.</p><div class="grid kpi compact-kpis">${kpiCard('Readiness',`${R.score}%`,'Release/spec/method/sample/competency')}${kpiCard('Forecast',fmtDate(p.forecastCompletion),'Current completion forecast')}${kpiCard('Budget',currency(state,pc.budget,true),'Project financial guardrail')}${kpiCard('Forecast cost',currency(state,pc.forecast,true),`${pc.variance>=0?'+':''}${pc.variancePct}% variance`)}</div><div class="modal-grid"><div class="field"><label>Programme priority</label><select id="pcPriority">${['Critical','High','Normal','Low'].map(x=>`<option ${x===p.priority?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>Business priority score</label><input id="pcScore" type="number" min="0" max="100" value="${Number(p.businessPriority)||50}"></div><div class="field"><label>Programme gate</label><select id="pcGate">${['Draft','Review','Released','Hold'].map(x=>`<option ${x===p.gateStatus?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>Required programme completion</label><input id="pcDue" type="date" value="${new Date(p.dueDate).toISOString().slice(0,10)}"></div><div class="field"><label>Programme budget</label><input id="pcBudget" type="number" min="0" value="${Number(p.budget)||0}"></div><div class="field"><label>Programme manager</label><select id="pcManager"><option value="">Unassigned</option>${state.staff.map(s=>`<option value="${s.id}" ${s.id===p.programmeManager?'selected':''}>${esc(s.name)} · ${esc(s.role)}</option>`).join('')}</select></div></div><label class="review-check"><input id="pcPropagate" type="checkbox" checked><span><strong>Apply programme due date to all open test legs</strong><small>Uncheck if individual leg due dates should remain unchanged.</small></span></label><div class="field"><label>Reason / planning note</label><textarea id="pcReason">${esc(p.changeReason||'Project planning inputs reviewed.')}</textarea></div><div class="callout"><strong>Release behaviour:</strong> a Released programme can still remain unscheduled when its active test specification is not released, a method requires development, samples are not ready, or no qualified resource is available.</div><div class="actions" style="margin-top:14px"><button id="saveProjectControls" class="btn primary">Save & Recalculate Laboratory Plan</button></div>`);
 document.getElementById('saveProjectControls').onclick=async()=>{
  const due=document.getElementById('pcDue').value;if(!due)return toast('A programme due date is required.');
  const newDue=new Date(due+'T17:00:00Z').toISOString(),newPriority=document.getElementById('pcPriority').value,old=JSON.stringify({priority:p.priority,businessPriority:p.businessPriority,gateStatus:p.gateStatus,dueDate:p.dueDate,budget:p.budget,programmeManager:p.programmeManager});
  p.priority=newPriority;p.businessPriority=Math.max(0,Math.min(100,Number(document.getElementById('pcScore').value)||0));p.gateStatus=document.getElementById('pcGate').value;p.dueDate=newDue;p.budget=Math.max(0,Number(document.getElementById('pcBudget').value)||0);p.programmeManager=document.getElementById('pcManager').value;p.changeReason=document.getElementById('pcReason').value.trim();
  for(const l of state.legs.filter(l=>l.programmeId===id)){l.priority=newPriority;if(document.getElementById('pcPropagate').checked&&!['Completed','Cancelled','Failed'].includes(l.status))l.dueDate=newDue;}
  state.audit.push(audit('Project planning controls changed',id,old,JSON.stringify({priority:p.priority,businessPriority:p.businessPriority,gateStatus:p.gateStatus,dueDate:p.dueDate,budget:p.budget,programmeManager:p.programmeManager,reason:p.changeReason})));
  const r=scheduleAll(state);state=r.data;state.settings.planDirty=false;lastPlanDiagnostics=r.diagnostics;await persist();closeModal();render();toast(`${id} updated; ${r.diagnostics.moved.length} bookings moved and ${r.diagnostics.unscheduled.length} remain unscheduled.`);
 };
}

