function applyBuilderTemplate(id){const templates={env:['ELEC-001','ENV-TC-004','ENV-HU-003','MECH-VIB-006','ELEC-002'],reliability:['ELEC-001','MECH-VIB-006','REL-005','MECH-DUR-009','ELEC-002'],full:['ELEC-001','ENV-TC-004','ENV-HU-003','MECH-VIB-006','EMC-007','REL-005','ELEC-002']},ids=templates[id]||[],d=getBuilderDraft(),total=Number(d.dutCount)||20;const now=Date.now();d.legs=ids.filter(mid=>state.methods.some(m=>m.id===mid&&m.active)).map((mid,i)=>({id:`BL-${now}-${i}`,kind:'existing',methodId:mid,legName:state.methods.find(m=>m.id===mid)?.name||mid,dutCount:total,populationMode:'Continue',dependencyMode:i===0?'Start':'Custom',dependsOn:[],staffId:'',staffPolicy:'Auto',sampleReadyOffset:0}));if(id==='env'&&d.legs.length>=5){d.legs[0].dependsOn=[];d.legs[1].dependsOn=[d.legs[0].id];d.legs[2].dutCount=Math.ceil(total/2);d.legs[2].populationMode='Group A';d.legs[2].dependsOn=[d.legs[1].id];d.legs[3].dutCount=Math.floor(total/2);d.legs[3].populationMode='Group B';d.legs[3].dependsOn=[d.legs[1].id];d.legs[4].dependsOn=[d.legs[2].id,d.legs[3].id];}else{for(let i=1;i<d.legs.length;i++)d.legs[i].dependsOn=[d.legs[i-1].id];}persist().then(()=>{render();toast(`${d.legs.length} editable validation legs loaded.`)})}
function costSettingsModal(){const c=state.settings.costFramework,skills=[...new Set(state.staff.flatMap(s=>s.skills||[]))].sort();openModal(`<h2>Cost Framework & Rate Card</h2><p class="small muted">Costs can be defined globally, by skillset, by individual resource and by specific test method. Method-specific overrides take precedence.</p><div class="modal-grid"><div class="field"><label>Currency</label><select id="cfCurrency">${['EUR','USD','GBP'].map(x=>`<option ${c.currency===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>Overhead (%)</label><input id="cfOver" type="number" min="0" value="${c.overheadPct}"></div><div class="field"><label>Planning contingency (%)</label><input id="cfCont" type="number" min="0" value="${c.contingencyPct}"></div><div class="field"><label>Default staff rate / h</label><input id="cfStaff" type="number" min="0" value="${c.defaultStaffRate}"></div><div class="field"><label>Default equipment rate / h</label><input id="cfEq" type="number" min="0" value="${c.defaultEquipmentRate}"></div></div><h3>Skillset labour rates</h3><div class="table-wrap"><table><thead><tr><th>Skill</th><th>Rate / h</th></tr></thead><tbody>${skills.map((sk,i)=>`<tr><td>${esc(sk)}</td><td><input class="skill-rate-input" data-skill="${esc(sk)}" type="number" min="0" value="${Number(c.skillRates?.[sk]||c.defaultStaffRate)}"></td></tr>`).join('')}</tbody></table></div><h3>Specific test cost overrides</h3><div class="list">${state.methods.slice(0,12).map(m=>{const o=c.methodOverrides?.[m.id]||{};return`<div class="list-row"><div><strong>${m.id} · ${esc(m.name)}</strong><small>${Object.keys(o).length?'Custom override active':'Uses skill/equipment/method defaults'}</small></div><button class="btn small" data-act="edit-method-cost" data-id="${m.id}">Edit</button></div>`}).join('')}</div><button id="saveCostFramework" class="btn primary">Save Global & Skill Rates</button>`);document.getElementById('saveCostFramework').onclick=async()=>{const old=JSON.stringify(c);Object.assign(c,{currency:document.getElementById('cfCurrency').value,overheadPct:Number(document.getElementById('cfOver').value)||0,contingencyPct:Number(document.getElementById('cfCont').value)||0,defaultStaffRate:Number(document.getElementById('cfStaff').value)||0,defaultEquipmentRate:Number(document.getElementById('cfEq').value)||0});for(const el of modalBody.querySelectorAll('.skill-rate-input'))c.skillRates[el.dataset.skill]=Number(el.value)||0;state.audit.push(audit('Cost framework changed','Settings',old,JSON.stringify(c)));await persist();closeModal();render();toast('Cost framework and skill rates updated.')};wireModalActions();}
function editCostBudgetModal(id){const p=state.programmes.find(x=>x.id===id);if(!p)return;const C=programmeCost(state,id);openModal(`<h2>${id} · Budget & Cost Target</h2><div class="grid kpi compact-kpis">${kpiCard('Current budget',currency(state,C.budget,true),'Financial guardrail')}${kpiCard('Forecast',currency(state,C.forecast,true),`${C.variance>=0?'+':''}${C.variancePct}% variance`)}${kpiCard('Actual to date',currency(state,C.actualToDate,true),'Completed work')}${kpiCard('Estimate to complete',currency(state,C.remaining,true),'Open work')}</div><div class="modal-grid"><div class="field"><label>Programme budget</label><input id="budgetValue" type="number" min="0" value="${Number(p.budget)||C.budget}"></div><div class="field"><label>Business priority score</label><input id="budgetPriority" type="number" min="0" max="100" value="${Number(p.businessPriority)||50}"></div></div><div class="field"><label>Reason / financial note</label><textarea id="budgetReason">Budget reviewed against current test scope and resource plan.</textarea></div><div class="actions"><button id="saveBudget" class="btn primary">Save Budget & Recalculate Cost</button></div>`);document.getElementById('saveBudget').onclick=async()=>{const old=p.budget;p.budget=Math.max(0,Number(document.getElementById('budgetValue').value)||0);p.businessPriority=Math.max(0,Math.min(100,Number(document.getElementById('budgetPriority').value)||0));p.changeReason=document.getElementById('budgetReason').value.trim();state.audit.push(audit('Programme budget changed',id,old,p.budget));await persist();closeModal();render();toast(`${id} budget updated to ${currency(state,p.budget,true)}.`)}}

async function builderAddCustom(){const d=getBuilderDraft(),name=document.getElementById('bcName')?.value.trim();if(!name)return toast('Enter a name for the new test.');const cat=document.getElementById('bcCat').value,eq=document.getElementById('bcEq').value,skill=document.getElementById('bcSkill').value,hist=developmentEstimateForNewTest(cat,eq,skill),id=`BL-CUSTOM-${Date.now()}`;d.legs.push({id,kind:'custom',tempId:`CUSTOM-${Date.now().toString().slice(-6)}`,name,legName:name,category:cat,equipmentType:eq,skill,executionHours:Number(document.getElementById('bcHours').value)||8,setupHours:4,teardownHours:2,analysisHours:4,devDays:hist.days,engineeringHours:hist.engineeringHours,technicianHours:hist.technicianHours,fixtureCost:Number(document.getElementById('bcFixture').value)||0,dutCount:Number(document.getElementById('bcDuts').value)||Math.min(8,d.dutCount),populationMode:'Continue',dependencyMode:d.legs.length?'Custom':'Start',dependsOn:d.legs.length?[d.legs.at(-1).id]:[],staffId:'',staffPolicy:'Auto',developmentEstimateBasis:hist.basis,developmentEstimateConfidence:hist.confidence});await persist();render();toast(`Development-gated leg added: estimated ${hist.days} days from ${hist.basis}.`)}
