function sparkline(readings,key,min,max){const a=(readings||[]).slice(-50);if(!a.length)return'<div class="empty">Waiting for data…</div>';const W=520,H=120,p=8,lo=Number.isFinite(Number(min))?Number(min):Math.min(...a.map(r=>Number(r.values[key]))),hi=Number.isFinite(Number(max))?Number(max):Math.max(...a.map(r=>Number(r.values[key]))),span=Math.max(.001,hi-lo),pts=a.map((r,i)=>`${p+i*(W-p*2)/Math.max(1,a.length-1)},${H-p-(Number(r.values[key])-lo)/span*(H-p*2)}`).join(' ');return`<svg class="live-spark" viewBox="0 0 ${W} ${H}"><polyline points="${pts}"/><line x1="0" x2="${W}" y1="${H-p-(Number(max)-lo)/span*(H-p*2)}" y2="${H-p-(Number(max)-lo)/span*(H-p*2)}" class="limit"/><line x1="0" x2="${W}" y1="${H-p-(Number(min)-lo)/span*(H-p*2)}" y2="${H-p-(Number(min)-lo)/span*(H-p*2)}" class="limit"/></svg>`}
function renderLive(){ensureLiveState(state);const sessions=state.liveSessions,open=state.liveAlerts.filter(a=>a.status==='Open'),activeId=state.settings.liveSession||sessions[0]?.id,s=sessions.find(x=>x.id===activeId)||sessions[0];if(!s)return pageHead('Live Test Monitor','No live sessions available.');state.settings.liveSession=s.id;const sum=liveSessionSummary(state,s),l=state.legs.find(x=>x.id===s.legId),m=state.methods.find(x=>x.id===s.methodId),p=state.programmes.find(x=>x.id===s.programmeId),last=sum.last;return pageHead('Live Test Monitor','Browser-based live data integration, anomaly detection and engineer alerts. Demo simulator works offline; HTTP JSON feeds can be configured for real test equipment gateways.',`<button class="btn" data-act="connect-live" data-id="${s.id}">Connect Feed</button><button class="btn" data-act="configure-alerts" data-id="${s.id}">Alert Rules</button><button class="btn" data-route-jump="control">Escalation Center</button><button class="btn" data-act="inject-anomaly" data-id="${s.id}">Inject Demo Anomaly</button><button class="btn primary" data-act="toggle-live" data-id="${s.id}">${s.status==='Streaming'?'Pause':'Start'} Stream</button>`)+`<div class="live-session-tabs">${sessions.map(x=>`<button class="${x.id===s.id?'active':''}" data-live-session="${x.id}"><strong>${x.id}</strong><span>${x.legId} · ${x.status}</span></button>`).join('')}</div><div class="grid kpi visual-kpis">${kpiCard('Programme',p?.id||s.programmeId,p?.project||'')}${kpiCard('Test leg',l?.id||s.legId,l?.name||'')}${kpiCard('Method',m?.id||s.methodId,m?.name||'')}${kpiCard('Data points',sum.points,s.sourceType)}${kpiCard('Open alerts',sum.open,`${sum.alerts} total alerts`)}${kpiCard('Last update',last?fmtDate(last.timestamp,true):'—',s.status)}</div><div class="live-channel-grid">${s.channels.map(c=>{const v=last?.values?.[c.key];return`<section class="card live-channel"><div class="section-title"><h2>${esc(c.name)}</h2><span class="hint">${v??'—'} ${esc(c.unit)}</span></div>${sparkline(s.readings,c.key,c.min,c.max)}<div class="live-limits"><span>Min ${c.min}${c.unit}</span><strong>Target ${c.target}${c.unit}</strong><span>Max ${c.max}${c.unit}</span></div></section>`}).join('')}</div><div class="grid section-grid equal" style="margin-top:14px">${section('Active / recent anomaly alerts',`<div class="list">${state.liveAlerts.filter(a=>a.sessionId===s.id).slice().sort((a,b)=>new Date(b.timestamp)-new Date(a.timestamp)).slice(0,12).map(a=>`<div class="list-row ${a.status==='Open'?'alert-open':''}"><div><strong>${a.id} · ${esc(a.channelName)} · ${esc(a.type)}</strong><small>${fmtDate(a.timestamp,true)} · ${a.value}${a.unit} · ${esc(a.message)}</small></div><div class="actions">${pill(a.status)}${state.operationalEvents?.some(e=>e.sourceType==='Live alert'&&e.sourceId===a.id)?'<span class="small muted">Escalated</span>':''}${a.status==='Open'?`<button class="btn small" data-act="ack-alert" data-id="${a.id}">Acknowledge</button>`:''}</div></div>`).join('')||'<div class="empty">No alerts.</div>'}</div>`,'Threshold, rate-of-change and rolling statistical anomaly detection')}${section('Live data integration contract',`<div class="callout"><strong>Supported prototype feeds</strong><p>Demo simulator, CSV/JSON snapshot import, or direct browser HTTP polling to a CORS-enabled equipment/gateway endpoint.</p><code>{ "timestamp":"2026-09-04T16:30:00Z", "values": { "temperature":125.2, "dut_voltage":12.01 } }</code></div><div class="actions"><button class="btn" data-act="import-live-csv" data-id="${s.id}">Import CSV / JSON</button><button class="btn" data-act="auto-report" data-id="${s.legId}">Generate Test Report</button></div>`,'Production deployment would normally use a secure gateway / message broker rather than expose equipment directly to the browser')}</div>`;}
function startLiveTicker(){if(liveTimer)clearInterval(liveTimer);liveTimer=setInterval(async()=>{if(route!=='live'){clearInterval(liveTimer);liveTimer=null;return;}const s=state.liveSessions.find(x=>x.id===(state.settings.liveSession||state.liveSessions[0]?.id));if(!s||s.status!=='Streaming')return;if(s.sourceType==='Demo simulator'){simulateLiveTick(state,s.id);syncLiveEscalations(state);liveTickCounter++;if(liveTickCounter%4===0)await persist();render();}else if(s.sourceType==='HTTP JSON'&&s.sourceUrl){try{const r=await fetch(s.sourceUrl,{cache:'no-store'});if(!r.ok)throw new Error(`HTTP ${r.status}`);const obj=await r.json(),rows=Array.isArray(obj)?obj:[obj];for(const x of rows)ingestReading(state,s.id,x.values||x,x.timestamp||new Date().toISOString());syncLiveEscalations(state);s.connectionError='';await persist();render();}catch(err){s.connectionError=err.message;}}},Math.max(2000,Number(state.liveSessions.find(x=>x.id===(state.settings.liveSession||state.liveSessions[0]?.id))?.pollSeconds||3)*1000));}
function renderDUTs(){return pageHead('DUTs & Specimens','Genealogy, programme allocation, failed/removed units and complete test journey')+`<div class="filters"><select id="dutProg"><option value="">All programmes</option>${state.programmes.map(p=>`<option value="${p.id}">${p.id} · ${esc(p.project)}</option>`).join('')}</select><select id="dutStatus"><option value="">All status</option><option>Available</option><option>Failed</option><option>Removed</option></select><input id="dutFilter" placeholder="Serial number or DUT ID"></div><section class="card"><div class="table-wrap"><table><thead><tr><th>DUT</th><th>Serial</th><th>Product</th><th>Programme</th><th>Group</th><th>Status</th><th>Legs assigned</th><th>Results</th></tr></thead><tbody id="dutBody"></tbody></table></div></section>`}
function renderDutTable(){const pr=document.getElementById('dutProg')?.value||'',st=document.getElementById('dutStatus')?.value||'',f=(document.getElementById('dutFilter')?.value||'').toLowerCase();const rows=state.duts.filter(d=>(!pr||d.programmeId===pr)&&(!st||d.status===st)&&(!f||`${d.id} ${d.serialNumber}`.toLowerCase().includes(f)));document.getElementById('dutBody').innerHTML=rows.map(d=>{const ls=state.legs.filter(l=>l.dutIds.includes(d.id)),rs=state.results.filter(r=>r.dutId===d.id);return `<tr><td><span class="link mono" data-entity="dut" data-id="${d.id}">${d.id}</span></td><td>${d.serialNumber}</td><td>${esc(d.product)}</td><td>${d.programmeId}</td><td>${d.group}</td><td>${pill(d.status)}</td><td>${ls.length}</td><td>${rs.length} · ${rs.some(r=>r.status==='FAIL')?pill('FAIL'):rs.length?pill('PASS'):'—'}</td></tr>`}).join('');wireEntities(document.getElementById('dutBody'));}

function renderLibrary(){const methods=state.methods,devOpen=state.devTasks.filter(d=>!d.completeDate);return pageHead('Test Library & Learning','Released methods, actual time learning, efficiency, granular cost, competency and traceable lessons learned',`<button class="btn" data-act="request-new-test">＋ Request New Test</button><button class="btn primary" data-act="jump-builder">＋ Build Programme</button>`)+`<div class="grid kpi">${kpiCard('Released methods',methods.filter(m=>m.active).length,'Reusable standards')}${kpiCard('Needs development',methods.filter(m=>!m.active).length,`${devOpen.length} open development tasks`)}${kpiCard('Learning-enabled',methods.filter(m=>methodTimeMetrics(state,m.id).runs>=3).length,'≥3 actual runs inform planning')}${kpiCard('Single-person methods',methods.filter(m=>methodLessons(m.id).qualified===1).length,'Competency continuity risk')}${kpiCard('Historical runs',state.testRuns.length,'Time-learning evidence')}${kpiCard('Historical issues',state.issues.length,'Traceable lessons evidence')}</div><section class="card"><div class="table-wrap"><table><thead><tr><th>Method</th><th>State</th><th>Library → learned time</th><th>Efficiency</th><th>Resource / skill</th><th>Typical cost</th><th>History / lessons</th><th>Competency</th><th>Actions</th></tr></thead><tbody>${methods.map(m=>{const L=methodLessons(m.id),T=methodTimeMetrics(state,m.id),C=methodCost(state,m.id,8);return`<tr><td><span class="link mono" data-entity="method" data-id="${m.id}">${m.id}</span><div><strong>${esc(m.name)}</strong></div><div class="small muted">${m.category} · Rev ${m.revision}</div></td><td>${pill(m.active?'Released':'Development')}</td><td><strong>${m.setupHours+m.executionHours+m.teardownHours+m.analysisHours}h → ${T.learned.total}h</strong><div class="small muted">${T.runs} runs · ${T.confidence}% confidence</div></td><td><strong>${T.productivePct}% productive</strong><div class="small muted">FTR ${T.firstTimeRightPct}% · queue ${T.queuePct}% · setup ${T.setupPct}%</div></td><td>${m.equipmentType}<div class="small muted">${m.requiredSkills.join(', ')}</div></td><td><strong>${currency(state,C.total,true)}</strong><div class="small muted">8-DUT estimate</div></td><td><button class="link-button" data-act="lesson-provenance" data-id="${m.id}">${L.issues} source issues · ${L.delayHours}h delay</button><div class="small muted">${esc(L.topIssue)}</div></td><td><strong>${L.qualified}</strong><div class="small muted">independent+</div></td><td><div class="actions vertical-actions"><button class="btn small" data-act="edit-method-cost" data-id="${m.id}">Cost</button><button class="btn small" data-act="log-method-time" data-id="${m.id}">Time</button>${T.runs>=3?`<button class="btn small" data-act="apply-learned-standard" data-id="${m.id}">Adopt learned</button>`:''}</div></td></tr>`}).join('')}</tbody></table></div></section>`}
function renderEquipment(){const u=resourceUtilisation(state),map=Object.fromEntries(u.equipment.map(x=>[x.id,x]));return pageHead('Equipment Register','Capability, utilisation, calibration, maintenance and planning availability',`<button class="btn" data-act="export-equipment-csv">⇩ Equipment CSV</button>`)+`<div class="grid kpi">${kpiCard('Assets',state.equipment.length,'Registered laboratory equipment')}${kpiCard('Available',state.equipment.filter(e=>e.status==='Available').length,'Current asset status')}${kpiCard('Maintenance',state.equipment.filter(e=>e.status==='Maintenance').length,'Unavailable by status')}${kpiCard('Breakdown',state.equipment.filter(e=>e.status==='Breakdown').length,'Corrective maintenance')}${kpiCard('Calibration risk',state.equipment.filter(e=>['red','amber'].includes(calibrationStatus(e,state).tone)).length,'Expired or due ≤60d')}${kpiCard('Portfolio utilisation',`${u.equipmentAvg}%`,'Next 4 weeks')}</div><section class="card"><div class="table-wrap"><table><thead><tr><th>Asset</th><th>Type / Capability</th><th>Manufacturer</th><th>Location</th><th>Status</th><th>Capacity</th><th>Utilisation</th><th>Calibration</th><th>Maintenance</th></tr></thead><tbody>${state.equipment.map(e=>{const c=calibrationStatus(e,state),ut=map[e.id]?.pct||0;return `<tr><td><span class="link mono" data-entity="equipment" data-id="${e.id}">${e.id}</span><div class="muted small">${e.assetNumber} · ${e.serialNumber}</div></td><td><strong>${esc(e.name)}</strong><div class="muted small">${esc(e.capability)}</div></td><td>${e.manufacturer}<div class="muted small">${e.model}</div></td><td>${e.location}</td><td>${pill(e.status)}</td><td>${e.capacity}</td><td><div class="bar-head"><span>${ut}%</span></div><div class="heat"><span style="width:${ut}%"></span></div></td><td><span class="pill ${c.tone}">${c.label}</span><div class="muted small">${fmtDate(e.calibrationDue)}</div></td><td>${fmtDate(e.maintenanceDate)}</td></tr>`}).join('')}</tbody></table></div></section>`}

function renderCalibration(){const current=state.equipment.filter(e=>e.calibrationRequired).map(e=>{const s=calibrationStatus(e,state),c=s.calibration,next=nextScheduledCalibration(state,e.id);return{e,c,next,s}}).sort((a,b)=>(a.s.days??999)-(b.s.days??999));const affected=state.bookings.filter(b=>{const e=state.equipment.find(x=>x.id===b.equipmentId);if(!e?.calibrationRequired)return false;const c=calibrationAt(state,e.id,b.start,{allowScheduled:true});return !c||new Date(c.dueDate)<new Date(b.end)}).length;return pageHead('Calibration Management','Validity, warning horizons, certificates and planning impact',`<button class="btn" data-act="add-calibration">＋ Add Calibration</button><button class="btn" data-act="export-cal-csv">⇩ CSV</button>`)+`<div class="grid kpi">${kpiCard('Valid',current.filter(x=>x.s.tone==='green').length,'Beyond 60-day warning')}${kpiCard('Due ≤60d',current.filter(x=>x.s.tone==='amber').length,'Amber warning')}${kpiCard('Expired / ≤7d',current.filter(x=>x.s.tone==='red').length,'Planning blocker / urgent')}${kpiCard('Calibration records',state.calibrations.length,'Current, historical + scheduled')}${kpiCard('Future tests affected',affected,'Effective calibration checked at planned use')}${kpiCard('Warning thresholds',state.settings.calibrationWarningDays.join(' / ')+'d','Configurable in Administration')}</div><section class="card"><div class="table-wrap"><table><thead><tr><th>Equipment</th><th>Current calibration</th><th>Date</th><th>Due</th><th>Status</th><th>Next planned</th><th>Provider</th><th>Certificate</th><th>As found / left</th></tr></thead><tbody>${current.map(x=>`<tr><td><span class="link mono" data-entity="equipment" data-id="${x.e.id}">${x.e.id}</span><div>${esc(x.e.name)}</div></td><td class="mono">${x.c?.id||'—'}</td><td>${fmtDate(x.c?.calibrationDate)}</td><td>${fmtDate(x.c?.dueDate)}</td><td><span class="pill ${x.s.tone}">${x.s.label}</span></td><td>${x.next?`<span class="pill blue">Scheduled</span><div class="muted small">${fmtDate(x.next.calibrationDate,true)} · ${esc(x.next.id)}</div>`:'—'}</td><td>${esc(x.c?.provider||'—')}</td><td>${x.c?`<a class="link" href="${esc(x.c.certificatePath)}" target="_blank" rel="noopener">${esc(x.c.certificateNumber)}</a>`:'—'}</td><td>${esc(x.c?.asFound||'—')} / ${esc(x.c?.asLeft||'—')}</td></tr>`).join('')}</tbody></table></div></section>`}

function renderPeople(){const u=resourceUtilisation(state),um=Object.fromEntries(u.staff.map(x=>[x.id,x])),risks=skillsRisks(state);return pageHead('People & Skills','Competency, authorisation, availability, workload and single-point qualification risks')+`<div class="grid kpi">${kpiCard('Staff',state.staff.length,'Technicians, engineers, specialists, manager')}${kpiCard('Staff utilisation',`${u.staffAvg}%`,'Attended planning load')}${kpiCard('Single-point skills',risks.filter(r=>r.count===1).length,'Only one independent operator')}${kpiCard('Qualification gaps',risks.filter(r=>r.count===0).length,'No independent coverage')}${kpiCard('Methods covered',`${pct(state.methods.length-risks.filter(r=>r.count===0).length,state.methods.length)}%`,'At least one independent qualification')}${kpiCard('People unavailable',state.staff.filter(s=>s.availability.some(a=>new Date(a.end)>DEMO_NOW)).length,'Future leave / training blocks')}</div><div class="grid section-grid"><section class="card"><div class="section-title"><h2>Staff workload</h2></div><div class="table-wrap"><table><thead><tr><th>Person</th><th>Role / Team</th><th>Skills</th><th>Qualifications</th><th>Availability</th><th>Workload</th></tr></thead><tbody>${state.staff.map(s=>{const ut=um[s.id]?.pct||0;return `<tr><td><span class="link" data-entity="staff" data-id="${s.id}">${esc(s.name)}</span><div class="mono small muted">${s.id}</div></td><td>${esc(s.role)}<div class="muted small">${esc(s.team)}</div></td><td>${s.skills.join(', ')}</td><td>${s.qualifications.length}<div class="muted small">${s.proficiency}</div></td><td>${s.availability.map(a=>`${fmtDate(a.start)}–${fmtDate(a.end)} ${a.reason}`).join('<br>')||'Available'}</td><td>${ut}%<div class="heat"><span style="width:${ut}%"></span></div></td></tr>`}).join('')}</tbody></table></div></section>${section('Single-point competency risks',risks.slice(0,15).map(r=>`<div class="list-row"><div><strong>${r.methodId} · ${esc(r.name)}</strong><small>${r.count?esc(r.people):'No independent qualified person'}</small></div><span class="pill ${r.count===0?'red':'amber'}">${r.count} qualified</span></div>`).join('')||'<div class="empty">No coverage risks.</div>','Independent / Reviewer / Expert levels')}</div>`}

function renderAnalytics(){const p=periodRange(),PM=periodMetrics(state,p.start,p.end),TR=periodTrend(state,p.start,p.end),IA=issueAnalytics(state,p.start,p.end),E=efficiencyMetrics(state,p.start,p.end),recs=operationalRecommendations(state);const methodRows=state.methods.map(m=>({m,t:methodTimeMetrics(state,m.id)})).filter(x=>x.t.runs>0).sort((a,b)=>Math.abs(b.t.durationVariancePct)-Math.abs(a.t.durationVariancePct)).slice(0,15);return pageHead('Reports / Analytics & Test Intelligence','Period-selectable quality, throughput, time-learning, efficiency, issue provenance and automatically proposed improvements',`<button class="btn" data-act="export-kpi-csv">⇩ KPI CSV</button>`)+periodControls()+`<div class="grid kpi visual-kpis">${drillKpiCard('Productive test time',`${E.productiveTestPct}%`,'Direct execution / total cycle incl. queue','productive')}${drillKpiCard('First-time-right',`${E.firstTimeRightPct}%`,'PASS without rework','ftr')}${drillKpiCard('Queue loss',`${E.queueLossPct}%`,'Waiting inside test cycle','queue')}${drillKpiCard('Setup burden',`${E.setupPct}%`,'Setup / actual execution cycle','setup')}${drillKpiCard('Hands-on ratio',`${E.handsOnPct}%`,'Attended staff / elapsed test hours','hands-on')}${drillKpiCard('Automation leverage',`${E.automationLeveragePct}%`,'Execution hours on unattended-capable tests','automation')}${drillKpiCard('Rework burden',`${E.reworkBurdenPct}%`,'Rework hours / execution cycle','rework')}${drillKpiCard('Development efficiency',`${E.developmentEfficiencyPct}%`,'Estimated / actual development effort','development')}</div><div class="grid section-grid equal">${section('Throughput & issue trend',trendViz(TR),`${TR.mode} buckets`)}${section('Outcome & root cause',outcomeViz(PM)+rootCauseDonut(IA.rootCauses),'Lessons are drillable from Test Library / programme builder')}</div><div class="grid section-grid equal" style="margin-top:14px">${section('Test-cycle efficiency composition',`<div class="efficiency-stack"><div style="--w:${E.executionSharePct}"><span>Execution ${E.executionSharePct}%</span></div><div style="--w:${E.setupPct}"><span>Setup ${E.setupPct}%</span></div><div style="--w:${E.analysisPct}"><span>Analysis ${E.analysisPct}%</span></div><div style="--w:${E.teardownPct}"><span>Teardown ${E.teardownPct}%</span></div></div><div class="callout"><strong>Value-added / productive test time = ${E.productiveTestPct}%</strong><p>This measures actual test execution/exposure as a share of the full cycle including queue/waiting. Higher is generally better, subject to method requirements.</p></div>`,'Execution share is a core laboratory efficiency KPI')}${section('Automatic improvement proposals',`<div class="decision-list">${recs.slice(0,10).map(r=>`<div><span class="decision-icon">${r.type==='Capacity'?'▥':r.type==='Asset service'?'⚙':'!'}</span><div><strong>${esc(r.title)}</strong><p>${esc(r.detail)} <b>Proposal:</b> ${esc(r.solution)} <span class="muted">${esc(r.impact)} · ${r.confidence} confidence</span></p>${r.action?`<button class="btn small" data-act="recommendation-action" data-id="${r.id}">Apply / Review</button>`:''}</div></div>`).join('')}</div>`,'Derived from resource, issue, time-learning and asset-service data')}</div><div style="margin-top:14px">${section('Method time learning — actual development and test execution feedback',`<div class="table-wrap"><table><thead><tr><th>Method</th><th>Runs</th><th>Library total</th><th>Learned total</th><th>Productive %</th><th>Queue %</th><th>FTR</th><th>Development actual</th><th>Action</th></tr></thead><tbody>${methodRows.map(({m,t})=>`<tr><td><span class="link mono" data-entity="method" data-id="${m.id}">${m.id}</span><div class="small muted">${esc(m.name)}</div></td><td>${t.runs}</td><td>${m.setupHours+m.executionHours+m.teardownHours+m.analysisHours}h</td><td><strong>${t.learned.total}h</strong><div class="small muted">${t.durationVariancePct>=0?'+':''}${t.durationVariancePct}% historical variance</div></td><td>${t.productivePct}%</td><td>${t.queuePct}%</td><td>${t.firstTimeRightPct}%</td><td>${t.development.engineeringHours+t.development.technicianHours}h<div class="small muted">${t.development.tasks} dev tasks</div></td><td><button class="btn small" data-act="log-method-time" data-id="${m.id}">Log</button>${t.runs>=3?`<button class="btn small" data-act="apply-learned-standard" data-id="${m.id}">Adopt</button>`:''}</td></tr>`).join('')}</tbody></table></div>`,'Future planning automatically uses learned component times when at least three completed runs exist')}</div>`;}
function renderAdmin(){const d=runDiagnostics(state);const examples=[['LabOS-Test-Programme-Template.pdf','Test programme template'],['LabOS-Cost-Framework-Guide.pdf','Cost framework guide'],['LabOS-Sample-Test-Report.pdf','Completed test report example'],['LabOS-Method-Development-Plan.pdf','New-method development plan'],['LabOS-Cost-Rate-Card.csv','Editable example rate card'],['LabOS-Test-Programme-Template.csv','Programme import/build example'],['LabOS-Requirements-Import-Template.csv','Requirements import / coverage example'],['LabOS-Specification-Review-Checklist.csv','Specification release checklist'],['LabOS-Opportunity-Pipeline-Template.csv','Potential-project capacity pipeline template'],['LabOS-Maintenance-Plan-Template.csv','Equipment maintenance policy template'],['LabOS-Audit-Checklist-ISO17025.csv','ISO/IEC 17025 internal readiness checklist'],['LabOS-Audit-Checklist-IATF16949.csv','IATF internal readiness checklist'],['LabOS-Live-Data-Example.csv','Live test-data import example'],['LabOS-Live-Feed-Schema.json','Live equipment/gateway feed schema'],['LabOS-Efficiency-Metrics-Guide.csv','Laboratory efficiency metric definitions'],['LabOS-Escalation-Matrix.csv','Exception severity / notification / replanning matrix'],['LabOS-Validation-Network-Example.csv','Parallel / sequential / join validation-network example']];return pageHead('Administration / Demo','Persistence, example artefacts, scenarios, audit history and deterministic system verification')+`<div class="grid section-grid equal"><section class="card pad"><h2 style="margin-top:0">Demo & Data</h2><div class="detail-grid"><div class="detail"><small>Version</small><strong>LabOS Prototype v${APP_VERSION}</strong></div><div class="detail"><small>Persistence</small><strong>IndexedDB + fallback</strong></div><div class="detail"><small>Demo actor</small><strong>${esc(state.settings.actor)}</strong></div></div><div class="actions"><button class="btn" data-act="export-json">⇩ Export Data</button><button class="btn" data-act="import-json">⇧ Import Data</button><button class="btn danger" data-act="reset-demo">↺ Reset Demo Data</button></div><div class="field"><label>Demo actor</label><input id="actorInput" value="${esc(state.settings.actor)}"></div><button class="btn small" data-act="save-actor">Save actor</button><p class="small muted">Prototype audit history is browser-local and is not a validated electronic-signature or production audit system.</p></section>${section('System Data Integrity',`<div class="callout ${d.overall==='PASS'?'':'danger'}"><strong>${d.overall}</strong> · ${d.pass}/${d.checks.length} automated checks passing.</div><div class="list">${d.checks.map(c=>`<div class="checkline"><span class="${c.ok?'diag-pass':'diag-fail'}">${c.ok?'PASS':'FAIL'}</span><strong>${esc(c.name)}</strong><span class="small muted">${esc(c.detail)}</span></div>`).join('')}</div><div style="padding:12px"><button class="btn primary" data-act="verify">✓ Run System Verification</button></div>`,'Verification uses current canonical browser data')}</div><div class="grid section-grid equal" style="margin-top:14px">${section('Operational example files',examples.map(([f,n])=>`<a class="doc-tile" href="${f}" target="_blank" rel="noopener"><div class="doc-icon">${f.endsWith('.pdf')?'PDF':f.endsWith('.json')?'JSON':'CSV'}</div><div><strong>${esc(n)}</strong><small>${f}</small></div></a>`).join(''),'Included in the flat GitHub package; no external services required')}${section('What-if scenario',scenarioPanel())}</div><div class="grid section-grid equal" style="margin-top:14px">${section('Calibration warning thresholds',`<div class="card pad" style="border:0;box-shadow:none"><div class="field"><label>Warning days (comma separated)</label><input id="calWarn" value="${state.settings.calibrationWarningDays.join(', ')}"></div><button class="btn small" data-act="save-warnings">Save thresholds</button><p class="small muted">Current visual bands use urgent ≤7d, warning ≤60d. Thresholds are retained for future policy expansion.</p></div>`)}${section('Prototype control boundaries',`<div class="list"><div class="list-row"><div><strong>Operational controls represented</strong><small>Release gates · competency · calibration · sample readiness · resource conflicts · cost · audit · evidence</small></div>${pill('Demo')}</div><div class="list-row"><div><strong>Production controls intentionally excluded</strong><small>Authentication · electronic signatures · central DB · server security · concurrent edits · authoritative backup</small></div>${pill('Not production')}</div></div>`)}</div>${section('Audit History',`<div class="audit list">${state.audit.slice().reverse().slice(0,40).map(a=>`<div class="list-row"><span>${fmtDate(a.timestamp,true)}</span><strong>${esc(a.actor)}</strong><div><b>${esc(a.action)}</b> · ${esc(a.entity)}<small>${esc(a.previousValue)} ${a.previousValue||a.newValue?'→':''} ${esc(a.newValue)}</small></div></div>`).join('')}</div>`,'Latest 40 session/demo events')}`}
function reportIssueModal(prefProgramme='',prefLeg=''){const activeLegs=state.legs.filter(l=>!['Completed','Cancelled','Failed'].includes(l.status)),prefP=prefProgramme||state.legs.find(l=>l.id===prefLeg)?.programmeId||state.settings.planningProject||state.programmes[0]?.id||'';openModal(`<h2>Log Delay / Test Issue</h2><p class="small muted">One event record feeds issue analytics, escalation, lessons learned and—when applicable—the planning constraint engine.</p><div class="modal-grid"><div class="field"><label>Event type</label><select id="issType"><option value="sample_delay">Sample / DUT delay</option><option value="test_issue">Test execution issue</option><option value="equipment_issue">Equipment outage / interruption</option><option value="spec_issue">Bad / ambiguous specification</option><option value="resource_issue">Staff / qualification issue</option></select></div><div class="field"><label>Programme</label><select id="issProg">${state.programmes.map(p=>`<option value="${p.id}" ${p.id===prefP?'selected':''}>${p.id} · ${esc(p.project)}</option>`).join('')}</select></div><div class="field"><label>Affected test leg</label><select id="issLeg"><option value="">Programme-level</option>${activeLegs.map(l=>`<option value="${l.id}" data-prog="${l.programmeId}" ${l.id===prefLeg?'selected':''}>${l.id} · ${l.programmeId} · ${esc(l.name)}</option>`).join('')}</select></div><div class="field"><label>Equipment (if applicable)</label><select id="issEq"><option value="">None / not equipment-specific</option>${state.equipment.map(e=>`<option value="${e.id}">${e.id} · ${esc(e.name)}</option>`).join('')}</select></div><div class="field"><label>Specification (if applicable)</label><select id="issSpec"><option value="">None</option>${state.specifications.map(sp=>`<option value="${sp.id}">${sp.id} Rev ${esc(sp.revision)} · ${esc(sp.name)}</option>`).join('')}</select></div><div class="field"><label>Severity / escalation level</label><select id="issSeverity">${['Low','Medium','High','Critical'].map(x=>`<option ${x==='Medium'?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>Constraint / recovery until</label><input id="issUntil" type="datetime-local" value="${dayISO(3,12).slice(0,16)}"></div><div class="field"><label>Estimated delay impact (hours)</label><input id="issHours" type="number" min="0" step="1" value="24"></div></div><div class="field"><label>Issue description</label><textarea id="issDesc">Sample / test condition changed; planner must account for the new availability constraint.</textarea></div><div class="field"><label>Issue subtype</label><input id="issSubtype" value="Sample arrival delay"></div><div class="callout"><strong>Connected behaviour:</strong> the issue is classified for recurrence/lessons, generates an escalation event according to severity, and creates a planning constraint when relevant. You choose whether to leave the plan dirty, replan only this programme, or replan the whole portfolio.</div><div class="actions" style="margin-top:14px"><button id="saveIssue" class="btn">Save Only</button><button id="saveIssueProgram" class="btn primary">Save & Replan Programme</button><button id="saveIssuePortfolio" class="btn">Save & Replan Portfolio</button></div>`);const sync=()=>{const t=document.getElementById('issType').value,sub=document.getElementById('issSubtype'),desc=document.getElementById('issDesc');const map={sample_delay:['Sample arrival delay','Customer sample/DUT availability changed.'],test_issue:['Fixture / connection problem','Test execution issue requires recovery or repeat work.'],equipment_issue:['Equipment interruption','Equipment is unavailable until recovery.'],spec_issue:['Specification ambiguity','Specification ambiguity or missing acceptance criterion identified.'],resource_issue:['Qualification / staffing gap','Required competent resource is unavailable.']};sub.value=map[t][0];desc.value=map[t][1]};document.getElementById('issType').onchange=sync;const prog=document.getElementById('issProg'),legSel=document.getElementById('issLeg'),specSel=document.getElementById('issSpec');const filter=()=>{for(const o of [...legSel.options])if(o.value)o.hidden=o.dataset.prog!==prog.value;if(legSel.value&&legSel.selectedOptions[0]?.hidden)legSel.value='';for(const o of [...specSel.options])if(o.value)o.hidden=state.specifications.find(x=>x.id===o.value)?.programmeId!==prog.value;if(specSel.value&&specSel.selectedOptions[0]?.hidden)specSel.value=''};prog.onchange=filter;filter();if(prefLeg)legSel.value=prefLeg;const save=async(mode)=>{const type=document.getElementById('issType').value,pid=prog.value,legId=legSel.value||null,eqId=document.getElementById('issEq').value||null,specId=document.getElementById('issSpec').value||null,severity=document.getElementById('issSeverity').value,untilRaw=document.getElementById('issUntil').value,hours=Math.max(0,Number(document.getElementById('issHours').value)||0),description=document.getElementById('issDesc').value.trim(),issueType=document.getElementById('issSubtype').value.trim()||'Operational issue';if(!description)return toast('Describe the issue.');if(type==='equipment_issue'&&!eqId)return toast('Select the affected equipment for an equipment outage.');if(type!=='spec_issue'&&!untilRaw)return toast('Set the recovery / constraint end time.');const untilDate=untilRaw?new Date(untilRaw):null;if(untilDate&&Number.isNaN(untilDate.getTime()))return toast('Enter a valid recovery time.');const until=untilDate?untilDate.toISOString():null;const rootCause=type==='spec_issue'?'Bad Specification':type==='sample_delay'?'Sample / DUT':type==='equipment_issue'?'Equipment / Facility':type==='resource_issue'?'Planning / Resource':'Test Execution';const lesson=rootCause==='Bad Specification'?'Add a specification completeness/ambiguity gate before test release':rootCause==='Test Execution'?'Standardise pre-test setup checks and capture recurrent execution failure modes':rootCause==='Sample / DUT'?'Make confirmed sample-ready date a hard planning input':'Expose resource interruptions immediately and maintain contingency capacity';const iid=`ISS-${String((state.issues||[]).length+1).padStart(3,'0')}`,issue={id:iid,reportedAt:new Date().toISOString(),programmeId:pid,legId,testRunId:null,specificationId:specId,issueType,rootCause,severity,delayHours:hours,status:'Open',description,lesson,correctiveAction:lesson,owner:state.settings.actor};state.issues.push(issue);if(type!=='spec_issue'){const dtype=type==='resource_issue'?'test_issue':type;state.disruptions.push({id:`DSP-${String((state.disruptions||[]).length+1).padStart(3,'0')}`,type:dtype,status:'Active',programmeId:pid,legId,equipmentId:type==='equipment_issue'?eqId:null,reportedAt:new Date().toISOString(),effectiveUntil:until,reason:description,impactHours:hours,sourceIssueId:iid});state.settings.planDirty=true}if(specId&&rootCause==='Bad Specification'){const sp=state.specifications.find(x=>x.id===specId);if(sp){sp.qualityScore=Math.max(0,(Number(sp.qualityScore)||80)-5);sp.qualityFlags=[...new Set([...(sp.qualityFlags||[]),issueType])]}}recordOperationalIssueEvent(state,issue,{replanScope:'Programme'});detectRecurringLessons(state);state.audit.push(audit('Operational issue logged',iid,'',`${rootCause} · ${severity} · ${hours}h`));let diff=[];if(mode==='programme'){const before=capturePlanningSnapshot(state,`Before ${pid} issue replan`),r=scheduleProgramme(state,pid);state=r.data;state.settings.planDirty=false;lastPlanDiagnostics=r.diagnostics;diff=planningDiff(before,state,{programmeId:pid});state.settings.lastProgrammePlanDiff={programmeId:pid,timestamp:new Date().toISOString(),rows:diff};}else if(mode==='portfolio'){const before=capturePlanningSnapshot(state,'Before issue portfolio replan'),r=scheduleAll(state);state=r.data;state.settings.planDirty=false;lastPlanDiagnostics=r.diagnostics;diff=planningDiff(before,state);state.settings.lastPortfolioPlanDiff={timestamp:new Date().toISOString(),rows:diff};}await persist();closeModal();render();toast(mode==='programme'?`${iid} saved; ${pid} replanned with ${diff.length} booking change(s).`:mode==='portfolio'?`${iid} saved; portfolio replanned with ${diff.length} booking change(s).`:`${iid} saved; escalation created and planning marked for refresh.`)};document.getElementById('saveIssue').onclick=()=>save('none');document.getElementById('saveIssueProgram').onclick=()=>save('programme');document.getElementById('saveIssuePortfolio').onclick=()=>save('portfolio')}

function resolveDisruption(id){const d=(state.disruptions||[]).find(x=>x.id===id);if(!d)return;openModal(`<h2>Close Planning Constraint · ${d.id}</h2><div class="callout warning"><strong>Resolution requires evidence.</strong><p>A planning constraint is only released after the recovery action and evidence/reference are recorded. This creates an auditable closure trail.</p></div><div class="field"><label>Recovery / corrective action</label><textarea id="rdAction" placeholder="What was done to remove the constraint?"></textarea></div><div class="field"><label>Objective evidence / reference</label><textarea id="rdEvidence" placeholder="e.g. sample receipt GRN-2041, repair WO-1138, rerun report TR-0097, supplier confirmation..."></textarea></div><div class="field"><label>Verified by</label><select id="rdVerifier">${state.staff.map(s=>`<option value="${s.name}">${esc(s.name)} · ${esc(s.role)}</option>`).join('')}</select></div><button id="confirmResolveDisruption" class="btn primary">Verify Evidence & Close Constraint</button>`);document.getElementById('confirmResolveDisruption').onclick=async()=>{const action=document.getElementById('rdAction').value.trim(),evidence=document.getElementById('rdEvidence').value.trim(),verifier=document.getElementById('rdVerifier').value;if(!action||!evidence)return toast('Recovery action and objective evidence are both required.');d.status='Resolved';d.resolvedAt=new Date().toISOString();d.resolution={action,evidence,verifiedBy:verifier,verifiedAt:d.resolvedAt};const i=(state.issues||[]).find(x=>x.id===d.sourceIssueId);if(i){i.status='Closed';i.closureEvidence=[...(i.closureEvidence||[]),{action,evidence,verifiedBy:verifier,timestamp:d.resolvedAt}];}state.settings.planDirty=true;state.audit.push(audit('Planning disruption evidence-closed',id,'Active',`${action} · ${evidence}`));await persist();closeModal();render();toast(`${id} evidence verified and closed. Update the plan to release the constraint.`)}}

function scenarioPanel(){return `<div class="card pad" style="border:0;box-shadow:none"><div class="field"><label>Scenario</label><select id="scenarioType"><option value="equipment_unavailable">Equipment unavailable for 7 days</option><option value="staff_unavailable">Staff unavailable next week</option><option value="add_equipment">Add temporary thermal chamber</option></select></div><div class="field" id="scenarioTargetWrap"><label>Target</label><select id="scenarioTarget">${state.equipment.map(e=>`<option value="${e.id}">${e.id} · ${esc(e.name)}</option>`).join('')}</select></div><div class="actions"><button class="btn primary" data-act="apply-scenario">Apply & Replan</button>${state.settings.scenario?'<button class="btn" data-act="reset-scenario">Reset Scenario</button>':''}</div>${state.settings.scenario?`<div class="callout warning" style="margin-top:12px"><strong>Active:</strong> ${esc(state.settings.scenario.label||state.settings.scenario.type)}</div>`:''}</div>`}

function wireRoute(){wireEntities(main);for(const b of main.querySelectorAll('[data-act]'))b.addEventListener('click',handleAction);for(const b of main.querySelectorAll('[data-route-jump]'))b.addEventListener('click',()=>go(b.dataset.routeJump));for(const b of main.querySelectorAll('[data-booking]'))b.addEventListener('click',()=>showBooking(b.dataset.booking));if(route==='dashboard'){for(const x of ['dashProgramme','dashCustomer','dashCategory','dashPriority','dashStatus','dashEquipment','dashStaff']){const el=document.getElementById(x);if(el)el.addEventListener('change',async()=>{state.settings.dashboardFilters={programme:document.getElementById('dashProgramme').value,customer:document.getElementById('dashCustomer').value,category:document.getElementById('dashCategory').value,priority:document.getElementById('dashPriority').value,status:document.getElementById('dashStatus').value,equipment:document.getElementById('dashEquipment').value,staff:document.getElementById('dashStaff').value};await persist();render();});}wirePeriodControls()}if(route==='analytics')wirePeriodControls();if(route==='live'){for(const b of main.querySelectorAll('[data-live-session]'))b.onclick=async()=>{state.settings.liveSession=b.dataset.liveSession;await persist();render()};startLiveTicker();}if(route==='requirements'){for(const x of ['reqProg','reqStatus','reqCrit','reqCategory','reqAttention','reqFilter'])document.getElementById(x)?.addEventListener('input',renderReqTable);renderReqTable()}if(route==='specifications'){for(const x of ['specProg','specStatus','specAttention','specFilter'])document.getElementById(x)?.addEventListener('input',renderSpecTable);renderSpecTable()}if(route==='duts'){for(const x of ['dutProg','dutStatus','dutFilter'])document.getElementById(x).addEventListener('input',renderDutTable);renderDutTable()}if(route==='programmes'){for(const s of main.querySelectorAll('.priority-change'))s.addEventListener('change',()=>changePriority(s.dataset.id,s.value))}if(route==='planning'){const pp=document.getElementById('planningProject');if(pp)pp.onchange=async()=>{state.settings.planningProject=pp.value;await persist();render()};const f=document.getElementById('scenarioFocus');if(f)f.onchange=async()=>{state.settings.scenarioFocusProgramme=f.value;await persist();render()}}if(route==='builder')wireBuilder();if(route==='costs'){const c=document.getElementById('costProgramme');if(c)c.onchange=async()=>{state.settings.costProgramme=c.value;await persist();render()}}if(route==='capacity'){const h=document.getElementById('capacityHorizon'),m=document.getElementById('pipelineMode');if(h)h.onchange=async()=>{state.settings.capacityHorizon=Number(h.value);await persist();render()};if(m)m.onchange=async()=>{state.settings.pipelineMode=m.value;await persist();render()}}if(route==='custody'){const c=document.getElementById('custodyProgramme');if(c)c.onchange=async()=>{state.settings.custodyProgramme=c.value;await persist();render()};}if(route==='twin'){const t=document.getElementById('twinProgramme');if(t)t.onchange=async()=>{state.settings.twinProgramme=t.value;await persist();render()};}if(route==='knowledge'){const k=document.getElementById('knowledgeProgramme');if(k)k.onchange=async()=>{state.settings.knowledgeProgramme=k.value;await persist();render()};}if(route==='audit'){const s=document.getElementById('auditStandard');if(s)s.onchange=async()=>{state.settings.auditStandard=s.value;state.settings.auditRecord='';await persist();render()};const ar=document.getElementById('auditRecord');if(ar)ar.onchange=async()=>{const a=state.audits.find(x=>x.id===ar.value);if(a){state.settings.auditStandard=a.standard;state.settings.auditRecord=a.id;await persist();render()}}}if(route==='admin'){const t=document.getElementById('scenarioType');if(t)t.onchange=updateScenarioTargets;updateScenarioTargets();}}

function wireEntities(root){for(const el of root.querySelectorAll('[data-entity]'))el.addEventListener('click',e=>{e.preventDefault();showEntity(el.dataset.entity,el.dataset.id)})}

function wireModalActions(){for(const b of modalBody.querySelectorAll('[data-act]'))b.addEventListener('click',handleAction);wireEntities(modalBody);}
async function builderAddMethod(methodId){const d=getBuilderDraft(),m=state.methods.find(x=>x.id===methodId);if(!m)return;d.legs.push({id:`BL-${Date.now()}-${Math.floor(Math.random()*1000)}`,kind:'existing',methodId:m.id,legName:m.name,dutCount:Math.min(Number(d.dutCount)||8,m.dutCapacity||Number(d.dutCount)||8),populationMode:'Continue',dependencyMode:d.legs.length?'Sequential':'Start',staffId:'',staffPolicy:'Auto'});await persist();render();toast(`${m.id} added as test leg ${d.legs.length}.`)}
async function addPortfolioTestToBuilder(methodId){const d=getBuilderDraft(),m=state.methods.find(x=>x.id===methodId);if(!m)return;const last=d.legs.at(-1);d.legs.push({id:`BL-${Date.now()}-${Math.floor(Math.random()*1000)}`,kind:'existing',methodId:m.id,legName:m.name,dutCount:Math.min(Number(d.dutCount)||8,m.dutCapacity||Number(d.dutCount)||8),populationMode:'Continue',dependencyMode:last?'Custom':'Start',dependsOn:last?[last.id]:[],staffId:'',staffPolicy:'Auto'});state.audit.push(audit('Test added from portfolio','Programme Builder','',m.id));await persist();closeModal();go('builder');toast(`${m.id} added as the next validation leg.`)}
async function builderRemoveLeg(id){const d=getBuilderDraft();d.legs=d.legs.filter(x=>x.id!==id);if(d.legs[0])d.legs[0].dependencyMode='Start';await persist();render();}
async function builderMoveLeg(id,dir){const d=getBuilderDraft(),i=d.legs.findIndex(x=>x.id===id),j=i+dir;if(i<0||j<0||j>=d.legs.length)return;[d.legs[i],d.legs[j]]=[d.legs[j],d.legs[i]];d.legs[0].dependencyMode='Start';await persist();render();}
function showLessonProvenance(methodId){const m=state.methods.find(x=>x.id===methodId),L=methodLessons(methodId);if(!m)return;openModal(`<h2>${m.id} · Lessons Learned Provenance</h2><div class="callout"><strong>${L.issues} source issues across ${L.runs} completed runs</strong><p>${esc(L.recommendation)}</p></div><div class="table-wrap"><table><thead><tr><th>Date</th><th>Issue / root cause</th><th>Programme / leg / run</th><th>Engineer / technician</th><th>Equipment</th><th>Impact</th><th>Lesson</th></tr></thead><tbody>${L.sources.map(x=>`<tr><td>${fmtDate(x.issue.reportedAt,true)}</td><td><strong>${esc(x.issue.issueType)}</strong><div class="small muted">${esc(x.issue.rootCause)} · ${x.issue.id}</div></td><td>${x.programme?`<span class="link" data-entity="programme" data-id="${x.programme.id}">${x.programme.id}</span>`:'—'}<div class="small muted">${x.leg?.id||'—'} · ${x.run?.id||'—'}</div></td><td>${x.staff?`<span class="link" data-entity="staff" data-id="${x.staff.id}">${esc(x.staff.name)}</span>`:'Not attributed'}</td><td>${x.equipment?`<span class="link" data-entity="equipment" data-id="${x.equipment.id}">${x.equipment.id}</span>`:'—'}</td><td>${x.issue.delayHours||0}h · ${pill(x.issue.severity)}</td><td>${esc(x.issue.lesson||x.issue.correctiveAction||'—')}</td></tr>`).join('')||'<tr><td colspan="7" class="empty">No source issues for this method.</td></tr>'}</tbody></table></div>`);wireEntities(modalBody);}
function editMethodCostModal(id){const m=state.methods.find(x=>x.id===id),c=state.settings.costFramework,o=c.methodOverrides[id]||{};if(!m)return;openModal(`<h2>${m.id} · Specific Test Cost Definition</h2><p class="small muted">Blank fields inherit skill/equipment/method defaults. These overrides apply only to ${m.id}.</p><div class="modal-grid"><div class="field"><label>Labour rate / h</label><input id="moLab" type="number" min="0" value="${o.labourRate??''}" placeholder="${c.skillRates?.[m.requiredSkills?.[0]]||c.defaultStaffRate}"></div><div class="field"><label>Equipment rate / h</label><input id="moEq" type="number" min="0" value="${o.equipmentRate??''}"></div><div class="field"><label>Fixed consumables</label><input id="moFixed" type="number" min="0" value="${o.fixedConsumables??m.fixedConsumables??0}"></div><div class="field"><label>Consumables / DUT</label><input id="moDut" type="number" min="0" value="${o.consumablesPerDut??m.consumablesPerDut??0}"></div><div class="field"><label>External / subcontract cost</label><input id="moExt" type="number" min="0" value="${o.externalCost??m.externalCost??0}"></div></div><button id="saveMethodCost" class="btn primary">Save Test-Specific Cost Model</button>`);document.getElementById('saveMethodCost').onclick=async()=>{const val=id=>document.getElementById(id).value.trim(),num=id=>val(id)===''?undefined:Number(val(id));c.methodOverrides[id]={labourRate:num('moLab'),equipmentRate:num('moEq'),fixedConsumables:num('moFixed'),consumablesPerDut:num('moDut'),externalCost:num('moExt')};for(const k of Object.keys(c.methodOverrides[id]))if(c.methodOverrides[id][k]===undefined)delete c.methodOverrides[id][k];state.audit.push(audit('Test-specific cost model changed',id,'',JSON.stringify(c.methodOverrides[id])));await persist();closeModal();render();toast(`${id} cost definition updated.`)}}
function logLegTimeModal(id){const l=state.legs.find(x=>x.id===id),m=state.methods.find(x=>x.id===l?.methodId);if(!l||!m)return;const r=state.testRuns.find(x=>x.legId===id)||{},T=methodTimeMetrics(state,m.id);openModal(`<h2>${id} · Actual Test Time</h2><p class="small muted">Component time becomes part of the method learning history and updates future planning standards automatically after sufficient evidence.</p><div class="modal-grid">${[['Setup','ltSetup',r.actualSetupHours??m.setupHours],['Execution / exposure','ltExec',r.actualExecutionHours??m.executionHours],['Teardown','ltTear',r.actualTeardownHours??m.teardownHours],['Analysis / reporting','ltAnalysis',r.actualAnalysisHours??m.analysisHours],['Queue / waiting','ltQueue',r.queueHours??0],['Rework','ltRework',r.reworkHours??0]].map(([a,k,v])=>`<div class="field"><label>${a} hours</label><input id="${k}" type="number" min="0" step="0.1" value="${v}"></div>`).join('')}</div><div class="callout"><strong>Current learned total:</strong> ${T.learned.total}h from ${T.runs} runs · productive time ${T.productivePct}%.</div><button id="saveLegTime" class="btn primary">Save Actual Time</button>`);document.getElementById('saveLegTime').onclick=async()=>{let run=state.testRuns.find(x=>x.legId===id);const vals={actualSetupHours:Number(document.getElementById('ltSetup').value)||0,actualExecutionHours:Number(document.getElementById('ltExec').value)||0,actualTeardownHours:Number(document.getElementById('ltTear').value)||0,actualAnalysisHours:Number(document.getElementById('ltAnalysis').value)||0,queueHours:Number(document.getElementById('ltQueue').value)||0,reworkHours:Number(document.getElementById('ltRework').value)||0};const total=vals.actualSetupHours+vals.actualExecutionHours+vals.actualTeardownHours+vals.actualAnalysisHours;if(run)Object.assign(run,vals,{actualHours:total});else state.testRuns.push({id:`RUN-MAN-${String(state.testRuns.length+1).padStart(3,'0')}`,legId:id,programmeId:l.programmeId,methodId:l.methodId,plannedStart:l.plannedStart,plannedEnd:l.plannedEnd,actualStart:l.actualStart||new Date().toISOString(),actualEnd:l.actualEnd||new Date().toISOString(),equipmentId:l.equipmentId,staffId:l.staffId,status:'Completed',outcome:'PASS',actualHours:total,standardHours:m.setupHours+m.executionHours+m.teardownHours+m.analysisHours,delayHours:0,source:'Manual time learning',...vals});ensureTimeLearningState(state);state.audit.push(audit('Actual test time recorded',id,'',`${total}h`));await persist();closeModal();render();toast('Actual test time saved; learned planning times refreshed.')}}
function logMethodTimeModal(id){const leg=state.legs.find(l=>l.methodId===id&&l.status==='Completed')||state.legs.find(l=>l.methodId===id);if(leg)return logLegTimeModal(leg.id);toast('No test leg exists for this method yet. Add it to a programme first.');}
function logDevelopmentTimeModal(id){const d=state.devTasks.find(x=>x.id===id);if(!d)return;openModal(`<h2>${d.id} · Development Time</h2><div class="modal-grid"><div class="field"><label>Actual engineering hours</label><input id="devEngA" type="number" min="0" value="${d.actualEngineeringHours??d.estimatedEngineeringHours}"></div><div class="field"><label>Actual technician hours</label><input id="devTechA" type="number" min="0" value="${d.actualTechnicianHours??d.estimatedTechnicianHours}"></div><div class="field"><label>Actual elapsed days</label><input id="devDaysA" type="number" min="0" value="${d.actualElapsedDays??d.elapsedDays}"></div><div class="field"><label>Status</label><select id="devStatus">${['Queued','In Progress','Review','Completed'].map(x=>`<option ${x===d.status?'selected':''}>${x}</option>`).join('')}</select></div></div><button id="saveDevTime" class="btn primary">Save Development Actuals</button>`);document.getElementById('saveDevTime').onclick=async()=>{d.actualEngineeringHours=Number(document.getElementById('devEngA').value)||0;d.actualTechnicianHours=Number(document.getElementById('devTechA').value)||0;d.actualElapsedDays=Number(document.getElementById('devDaysA').value)||0;d.status=document.getElementById('devStatus').value;if(d.status==='Completed'&&!d.completeDate)d.completeDate=new Date().toISOString();ensureTimeLearningState(state);state.audit.push(audit('Development actual time updated',d.id,'',`${d.actualEngineeringHours+d.actualTechnicianHours}h`));await persist();closeModal();render();toast('Development learning updated.')}}
async function applyLearnedStandard(id){const m=state.methods.find(x=>x.id===id),T=methodTimeMetrics(state,id);if(!m||T.runs<3)return toast('At least three completed runs are required.');const old=`${m.setupHours}/${m.executionHours}/${m.teardownHours}/${m.analysisHours}`;m.setupHours=T.learned.setup;m.executionHours=T.learned.execution;m.teardownHours=T.learned.teardown;m.analysisHours=T.learned.analysis;m.standardUpdatedFromLearningAt=new Date().toISOString();state.audit.push(audit('Method standard updated from actual history',id,old,`${m.setupHours}/${m.executionHours}/${m.teardownHours}/${m.analysisHours}`));const r=scheduleAll(state);state=r.data;ensureTimeLearningState(state);await persist();closeModal();render();toast(`${id} standard updated; ${r.diagnostics.moved.length} bookings replanned.`)}
async function toggleLive(id){const s=state.liveSessions.find(x=>x.id===id);if(!s)return;s.status=s.status==='Streaming'?'Paused':'Streaming';state.audit.push(audit('Live stream status changed',id,'',s.status));await persist();render();}
async function injectAnomaly(id){const s=state.liveSessions.find(x=>x.id===id);if(!s)return;if(s.status!=='Streaming')s.status='Streaming';simulateLiveTick(state,id,{inject:true});const created=syncLiveEscalations(state);await persist();render();toast(`Demo anomaly injected; ${created} escalation event(s) created.`);}
async function ackAlert(id){acknowledgeAlert(state,id,state.settings.actor);const evt=state.operationalEvents.find(e=>e.sourceType==='Live alert'&&e.sourceId===id);if(evt)acknowledgeOperationalEvent(state,evt.id,state.settings.actor);state.audit.push(audit('Live alert acknowledged',id,'Open','Acknowledged'));await persist();render();}
function configureAlertsModal(id){const s=state.liveSessions.find(x=>x.id===id),rules=state.liveAlertRules.filter(r=>r.sessionId===id);if(!s)return;openModal(`<h2>${id} · Anomaly Alert Rules</h2><div class="table-wrap"><table><thead><tr><th>Channel</th><th>Enabled</th><th>Min</th><th>Max</th><th>Rate Δ</th><th>Z-score</th><th>Action</th></tr></thead><tbody>${rules.map(r=>{const c=s.channels.find(x=>x.key===r.channel);return`<tr><td>${esc(c?.name||r.channel)}</td><td><input class="ar" data-id="${r.id}" data-f="enabled" type="checkbox" ${r.enabled?'checked':''}></td><td><input class="ar mini-input" data-id="${r.id}" data-f="min" type="number" step="any" value="${r.min}"></td><td><input class="ar mini-input" data-id="${r.id}" data-f="max" type="number" step="any" value="${r.max}"></td><td><input class="ar mini-input" data-id="${r.id}" data-f="rateLimit" type="number" step="any" value="${r.rateLimit}"></td><td><input class="ar mini-input" data-id="${r.id}" data-f="zScore" type="number" step="0.1" value="${r.zScore}"></td><td><select class="ar" data-id="${r.id}" data-f="action"><option ${r.action==='Alert only'?'selected':''}>Alert only</option><option ${r.action==='Create issue'?'selected':''}>Create issue</option></select></td></tr>`}).join('')}</tbody></table></div><button id="saveAlertRules" class="btn primary">Save Alert Rules</button>`);document.getElementById('saveAlertRules').onclick=async()=>{for(const el of modalBody.querySelectorAll('.ar')){const r=state.liveAlertRules.find(x=>x.id===el.dataset.id),f=el.dataset.f;if(!r)continue;r[f]=el.type==='checkbox'?el.checked:(['min','max','rateLimit','zScore'].includes(f)?Number(el.value):el.value);}state.audit.push(audit('Live anomaly rules changed',id,'','Updated'));await persist();closeModal();render();toast('Live anomaly rules updated.')}}
function connectLiveModal(id){const s=state.liveSessions.find(x=>x.id===id);if(!s)return;openModal(`<h2>${id} · Connect Live Data Feed</h2><div class="modal-grid"><div class="field"><label>Source</label><select id="liveSource"><option ${s.sourceType==='Demo simulator'?'selected':''}>Demo simulator</option><option ${s.sourceType==='HTTP JSON'?'selected':''}>HTTP JSON</option></select></div><div class="field"><label>Polling interval (seconds)</label><input id="livePoll" type="number" min="2" value="${s.pollSeconds||3}"></div></div><div class="field"><label>HTTP endpoint (CORS-enabled)</label><input id="liveUrl" value="${esc(s.sourceUrl||'')}" placeholder="https://lab-gateway.example/api/live/test-123"></div><div class="callout"><strong>Expected JSON:</strong><code>{"timestamp":"...","values":{"temperature":125.1,"dut_voltage":12.0}}</code><p>Because this prototype is static, production integration should normally use a secure authenticated gateway/broker; direct browser access is only a demonstration pattern.</p></div><button id="saveLiveConnect" class="btn primary">Save Connection</button>`);document.getElementById('saveLiveConnect').onclick=async()=>{s.sourceType=document.getElementById('liveSource').value;s.sourceUrl=document.getElementById('liveUrl').value.trim();s.pollSeconds=Math.max(2,Number(document.getElementById('livePoll').value)||3);state.audit.push(audit('Live feed configuration changed',id,'',s.sourceType));await persist();closeModal();render();toast('Live feed configuration saved.')}}
function importLiveDataModal(id){openModal(`<h2>Import Live Data Snapshot</h2><p class="small muted">CSV first column must be timestamp; remaining headings must match channel keys. JSON can be one reading or an array.</p><input id="liveFile" type="file" accept=".csv,.json,application/json,text/csv"><button id="loadLiveFile" class="btn primary">Import & Evaluate</button>`);document.getElementById('loadLiveFile').onclick=async()=>{const f=document.getElementById('liveFile').files[0];if(!f)return toast('Choose a CSV or JSON file.');const txt=await f.text();let rows=[];if(f.name.toLowerCase().endsWith('.json')){const o=JSON.parse(txt);rows=Array.isArray(o)?o:[o]}else{const lines=txt.trim().split(/\r?\n/),h=lines.shift().split(',').map(x=>x.trim());rows=lines.map(line=>{const v=line.split(',');const values={};for(let i=1;i<h.length;i++)values[h[i]]=Number(v[i]);return{timestamp:v[0],values}})}for(const r of rows)ingestReading(state,id,r.values||r,r.timestamp||new Date().toISOString());state.audit.push(audit('Live data snapshot imported',id,f.name,`${rows.length} readings`));await persist();closeModal();render();toast(`${rows.length} readings imported and anomaly-checked.`)}}
function reportHtmlForLeg(id){const l=state.legs.find(x=>x.id===id),m=state.methods.find(x=>x.id===l?.methodId),p=state.programmes.find(x=>x.id===l?.programmeId),st=state.staff.find(x=>x.id===l?.staffId),eq=state.equipment.find(x=>x.id===l?.equipmentId),res=state.results.filter(r=>r.legId===id),alerts=state.liveAlerts.filter(a=>a.legId===id),issues=state.issues.filter(i=>i.legId===id),run=state.testRuns.find(r=>r.legId===id),cal=state.calibrations.filter(c=>c.equipmentId===eq?.id&&c.result!=='Scheduled').sort((a,b)=>new Date(b.calibrationDate)-new Date(a.calibrationDate))[0],T=m?methodTimeMetrics(state,m.id):null,status=res.some(r=>r.status==='FAIL')?'FAIL':l?.status==='Completed'?'PASS':'IN PROGRESS';return`<!doctype html><html><head><meta charset="utf-8"><title>${id} Test Report</title><style>body{font:13px Arial;margin:36px;color:#17323a}h1{color:#087f78}.meta{display:grid;grid-template-columns:repeat(3,1fr);gap:8px}.box{border:1px solid #ccd;padding:8px}table{width:100%;border-collapse:collapse;margin:12px 0}th,td{border:1px solid #ccd;padding:6px;text-align:left}.status{font-size:24px;font-weight:bold}</style></head><body><h1>LabOS Automated Test Report</h1><p>Prototype-generated technical report · ${new Date().toLocaleString()}</p><div class="status">${status}</div><div class="meta"><div class="box"><b>Programme</b><br>${p?.id} · ${esc(p?.project)}</div><div class="box"><b>Test leg</b><br>${id} · ${esc(l?.name)}</div><div class="box"><b>Method</b><br>${m?.id} Rev ${m?.revision}</div><div class="box"><b>Operator</b><br>${esc(st?.name||'—')}</div><div class="box"><b>Equipment</b><br>${eq?.id||'—'} · ${esc(eq?.name||'')}</div><div class="box"><b>Calibration</b><br>${cal?.certificateNumber||'—'} · due ${cal?fmtDate(cal.dueDate):'—'}</div></div><h2>DUT population</h2><p>${l?.dutIds.join(', ')}</p><h2>Results</h2><table><tr><th>DUT</th><th>Parameter</th><th>Value</th><th>Status</th></tr>${res.map(r=>`<tr><td>${r.dutId}</td><td>${esc(r.parameter)}</td><td>${esc(r.value)} ${esc(r.unit||'')}</td><td>${r.status}</td></tr>`).join('')}</table><h2>Execution efficiency</h2><p>Actual ${run?.actualHours??'—'}h · direct execution ${run?.actualExecutionHours??'—'}h · queue ${run?.queueHours??0}h · method productive ratio ${T?.productivePct??'—'}%.</p><h2>Anomalies / deviations</h2><table><tr><th>Type</th><th>Time</th><th>Detail</th><th>Status</th></tr>${alerts.map(a=>`<tr><td>Live alert</td><td>${fmtDate(a.timestamp,true)}</td><td>${esc(a.message)}</td><td>${a.status}</td></tr>`).join('')}${issues.map(i=>`<tr><td>${esc(i.issueType)}</td><td>${fmtDate(i.reportedAt,true)}</td><td>${esc(i.description)}</td><td>${i.status}</td></tr>`).join('')}</table><h2>Requirements & traceability</h2><p>${(l?.requirementIds||[]).join(', ')}</p><h2>Automated conclusion</h2><p>${status==='FAIL'?'At least one recorded result is outside acceptance criteria. Formal disposition and review are required.':status==='PASS'?'All recorded mandatory results pass the deterministic acceptance evaluation for this leg.':'Test remains open; this report is an interim engineering view.'}</p><hr><small>This is prototype automated reporting and is not a validated electronic signature or controlled production report approval system.</small></body></html>`}
function autoReportModal(id){const html=reportHtmlForLeg(id),l=state.legs.find(x=>x.id===id);if(!l)return;openModal(`<h2>${id} · Automated Test Report</h2><div class="callout"><strong>Automatically assembled from:</strong> method/revision, DUT genealogy, results, operator, equipment/calibration, live anomalies, issues, actual time, requirements and acceptance status.</div><iframe class="report-preview" title="Automated report preview" srcdoc="${esc(html)}"></iframe><div class="actions"><button id="downloadAutoReport" class="btn primary">Download Self-Contained HTML Report</button></div>`);document.getElementById('downloadAutoReport').onclick=async()=>{download(`LabOS-${id}-Automated-Test-Report.html`,html,'text/html');const rid=`RPT-${id}-${String(state.testReports.filter(r=>r.legId===id).length+1).padStart(2,'0')}`;state.testReports.push({id:rid,legId:id,programmeId:l.programmeId,generatedAt:new Date().toISOString(),generatedBy:state.settings.actor,status:l.status==='Completed'?'Draft Review':'Interim',format:'HTML'});state.documents.push({id:`DOC-${rid}`,type:'Automated Test Report',entityId:id,name:`${id} Automated Test Report`,path:null,generated:true});state.audit.push(audit('Automated test report generated',id,'',rid));await persist();toast(`${rid} generated.`)}}
async function recommendationAction(id){const r=operationalRecommendations(state).find(x=>x.id===id);if(!r)return;if(r.action==='apply-learned-standard')return applyLearnedStandard(r.entityId);if(r.action==='optimize-maintenance'){const o=optimizeMaintenancePlan(state,90),pl=scheduleAll(o.data);state=pl.data;ensureTimeLearningState(state);await persist();render();return toast(`Service plan optimized; ${pl.diagnostics.moved.length} bookings moved.`)}toast(r.solution);}

function renderControl(){
 ensureWorkflowState(state);detectRecurringLessons(state);const H=workflowHealth(state),ES=escalationSummary(state),LS=lessonSummary(state),events=ES.events.slice(0,30),lessons=LS.rows.slice(0,20),delays=(state.disruptions||[]).filter(d=>d.status==='Active').sort((a,b)=>new Date(a.effectiveUntil)-new Date(b.effectiveUntil));
 return pageHead('Exceptions, Escalation & Learning','One operational exception chain: anomaly / issue → notification → escalation → delay/blocker → local or portfolio replan → lesson learned → standard-time / process improvement',`<button class="btn" data-act="log-lesson">＋ Log Lesson</button><button class="btn" data-act="report-issue">＋ Log Issue / Delay</button><button class="btn primary" data-act="update-plan">↻ Replan Portfolio</button>`)+
 `<div class="workflow-ribbon card"><div><strong>1 · Detect</strong><span>Live anomaly, test issue, sample delay, spec defect or asset event</span></div><b>→</b><div><strong>2 · Escalate</strong><span>Severity, SLA, notification roles and containment</span></div><b>→</b><div><strong>3 · Replan</strong><span>Programme-only or portfolio schedule impact</span></div><b>→</b><div><strong>4 · Learn</strong><span>Automatic recurrence detection + source provenance</span></div></div>`+
 `<div class="grid kpi visual-kpis control-kpis">${drillKpiCard('Open events',H.open,H.overdue?`${H.overdue} escalation SLA overdue`:'Within acknowledgement SLA','events')}${drillKpiCard('Critical / high',`${H.critical} / ${H.high}`,`${H.unread} unread notifications`,'escalations')}${drillKpiCard('Active delays',H.activeDelays,`${H.planImpact} events can affect planning`,'delays')}${drillKpiCard('Open issues',H.openIssues,'Traceable to programme / test / cause','issues')}${drillKpiCard('Automatic lessons',H.automaticLessons,`${H.recurrences} recurring source occurrences`,'lessons')}${drillKpiCard('Lesson delay impact',`${H.lessonDelayHours}h`,`${H.manualLessons} manually captured lessons`,'lesson-impact')}</div>`+
 `<div class="grid section-grid equal">${section('Escalation queue',`<div class="list">${events.map(e=>{const p=state.programmes.find(x=>x.id===e.programmeId),l=state.legs.find(x=>x.id===e.legId);return`<div class="list-row escalation-row severity-${String(e.severity).toLowerCase()}"><div><strong>${e.id} · ${esc(e.title)}</strong><small>${fmtDate(e.timestamp,true)} · ${p?.id||e.programmeId||'—'} · ${l?.id||e.legId||'programme level'} · ${esc(e.detail)}</small><div class="small muted">${e.ownerRoles?.join(' → ')||'No notification roles'} · acknowledge by ${fmtDate(e.requiredAckBy,true)} · replan: ${e.replanScope}</div></div><div class="actions">${pill(e.severity)}${pill(e.status)}${e.status==='Open'?`<button class="btn small" data-act="ack-event" data-id="${e.id}">Acknowledge</button>`:''}${e.programmeId?`<button class="btn small" data-act="plan-programme" data-id="${e.programmeId}">Replan programme</button>`:''}</div></div>`}).join('')||'<div class="empty">No open escalations.</div>'}</div>`,'Live/test exceptions are converted to operational actions using the escalation matrix')}${section('Escalation framework',`<div class="table-wrap"><table><thead><tr><th>Severity</th><th>Ack SLA</th><th>Notify</th><th>Issue</th><th>Delay</th><th>Block test</th><th>Planning scope</th><th></th></tr></thead><tbody>${state.escalationRules.map(r=>`<tr><td>${pill(r.severity)}</td><td>${r.slaMinutes} min</td><td>${r.notifyRoles.join(', ')}</td><td>${r.createIssue?'Yes':'No'}</td><td>${r.createDelay?`${r.defaultDelayHours}h`:'No'}</td><td>${r.blockTest?'Yes':'No'}</td><td>${r.replanScope}</td><td><button class="btn small" data-act="edit-escalation" data-id="${r.id}">Edit</button></td></tr>`).join('')}</tbody></table></div>`,'Prototype notifications are in-app events; production would connect email/Teams/Slack/on-call services')}</div></div>`+
 `<div class="grid section-grid equal" style="margin-top:14px">${section('Active delays / planning constraints',`<div class="list">${delays.map(d=>{const l=state.legs.find(x=>x.id===d.legId);return`<div class="list-row"><div><strong>${d.id} · ${esc(d.reason)}</strong><small>${d.programmeId} · ${l?.id||'programme'} · impact ${d.impactHours||0}h · recovery ${fmtDate(d.effectiveUntil,true)}</small></div><div class="actions">${pill(d.status)}<button class="btn small" data-act="resolve-disruption" data-id="${d.id}">Close with evidence</button>${d.programmeId?`<button class="btn small primary" data-act="plan-programme" data-id="${d.programmeId}">Replan</button>`:''}</div></div>`}).join('')||'<div class="empty">No active planning constraints.</div>'}</div>`,'Delays are hard earliest-start / availability constraints, not just notes')}${section('Detected + captured lessons learned',`<div class="lesson-stream">${lessons.map(l=>`<button class="lesson-card interactive" data-act="lesson-detail" data-id="${l.id}"><div><strong>${esc(l.title)}</strong><small>${l.source} · ${l.methodId||'programme-level'} · ${l.occurrences||1} occurrence(s) · ${l.delayHours||0}h delay</small></div><div class="lesson-metrics"><span>${l.rootCause}</span><span>${l.confidence||100}% confidence</span><span>${l.trend||'Captured'}</span></div><p>${esc(l.lesson)}</p><small>Tap for source issues, runs, people and programmes →</small></button>`).join('')||'<div class="empty">No lessons detected yet.</div>'}</div>`,'Automatic lessons are regenerated from recurring issue families; manual lessons stay persistent')}</div>`+
 `<div style="margin-top:14px">${section('Notification / acknowledgement trail',`<div class="table-wrap"><table><thead><tr><th>Time</th><th>Severity</th><th>Role</th><th>Event</th><th>Message</th><th>Status</th></tr></thead><tbody>${state.notifications.slice().sort((a,b)=>new Date(b.timestamp)-new Date(a.timestamp)).slice(0,40).map(n=>`<tr><td>${fmtDate(n.timestamp,true)}</td><td>${pill(n.severity)}</td><td>${esc(n.role)}</td><td>${n.eventId}</td><td>${esc(n.message)}</td><td>${pill(n.status)}</td></tr>`).join('')||'<tr><td colspan="6" class="empty">No notification events.</td></tr>'}</tbody></table></div>`,'Provides a visible escalation trail without claiming production message delivery')}</div>`;
}

function showLessonDetail(id){ensureWorkflowState(state);detectRecurringLessons(state);const l=state.lessonsLearned.find(x=>x.id===id);if(!l)return;const issues=(l.sourceIssueIds||[]).map(id=>state.issues.find(i=>i.id===id)).filter(Boolean),runs=[...new Set([...(l.sourceRunIds||[]),...issues.map(i=>i.testRunId).filter(Boolean)])].map(id=>state.testRuns.find(r=>r.id===id)).filter(Boolean);openModal(`<h2>${l.id} · ${esc(l.title)}</h2><div class="callout ${l.source==='Automatic'?'warning':''}"><strong>${l.source} lesson · ${l.occurrences||1} occurrence(s) · ${l.confidence||100}% confidence</strong><p>${esc(l.lesson)}</p></div><div class="detail-grid"><div class="detail"><small>Method</small><strong>${l.methodId||'Programme-level'}</strong></div><div class="detail"><small>Root cause</small><strong>${esc(l.rootCause)}</strong></div><div class="detail"><small>Issue family</small><strong>${esc(l.issueType)}</strong></div><div class="detail"><small>Delay impact</small><strong>${l.delayHours||0}h</strong></div><div class="detail"><small>First / last seen</small><strong>${fmtDate(l.firstSeen||l.detectedAt)} → ${fmtDate(l.lastSeen||l.detectedAt)}</strong></div><div class="detail"><small>Programmes</small><strong>${(l.programmeIds||[]).join(', ')||'—'}</strong></div></div><h3>Source provenance</h3><div class="table-wrap"><table><thead><tr><th>Issue</th><th>Programme / leg</th><th>Run</th><th>Person</th><th>Equipment</th><th>Delay</th><th>Description</th></tr></thead><tbody>${issues.map(i=>{const leg=state.legs.find(x=>x.id===i.legId),run=state.testRuns.find(x=>x.id===i.testRunId),staff=state.staff.find(x=>x.id===(run?.staffId||leg?.staffId)),eq=state.equipment.find(x=>x.id===(run?.equipmentId||leg?.equipmentId));return`<tr><td>${i.id}<div class="small muted">${esc(i.issueType)}</div></td><td>${i.programmeId}<div class="small muted">${i.legId||'—'}</div></td><td>${run?.id||'—'}</td><td>${esc(staff?.name||'Not attributed')}</td><td>${eq?.id||'—'}</td><td>${i.delayHours||0}h</td><td>${esc(i.description)}</td></tr>`}).join('')||'<tr><td colspan="7" class="empty">No issue records linked.</td></tr>'}</tbody></table></div><div class="actions"><button class="btn" data-act="log-lesson" data-method="${l.methodId||''}">Add follow-up lesson</button>${l.methodId?`<button class="btn" data-act="lesson-provenance" data-id="${l.methodId}">Method issue provenance</button>`:''}</div>`);wireModalActions();}

function logLessonModal(methodId=''){const m=state.methods.find(x=>x.id===methodId);openModal(`<h2>Log Lesson Learned</h2><div class="modal-grid"><div class="field"><label>Method</label><select id="llMethod"><option value="">Programme-level / general</option>${state.methods.map(x=>`<option value="${x.id}" ${x.id===methodId?'selected':''}>${x.id} · ${esc(x.name)}</option>`).join('')}</select></div><div class="field"><label>Programme</label><select id="llProg"><option value="">General</option>${state.programmes.map(p=>`<option value="${p.id}">${p.id} · ${esc(p.project)}</option>`).join('')}</select></div><div class="field"><label>Root cause</label><select id="llRoot">${['Test Execution','Bad Specification','Sample / DUT','Equipment / Facility','Planning / Resource','Test Method / Development','Other'].map(x=>`<option>${x}</option>`).join('')}</select></div><div class="field"><label>Source run (optional)</label><select id="llRun"><option value="">None</option>${state.testRuns.slice().reverse().slice(0,80).map(r=>`<option value="${r.id}">${r.id} · ${r.methodId} · ${r.staffId}</option>`).join('')}</select></div></div><div class="field"><label>Lesson title</label><input id="llTitle" value="${m?`${m.id} operational lesson`:'Operational lesson'}"></div><div class="field"><label>What should be done differently next time?</label><textarea id="llText">Capture the condition, preventive action and verification of effectiveness for future programmes.</textarea></div><button id="saveLesson" class="btn primary">Save Lesson</button>`);document.getElementById('saveLesson').onclick=async()=>{const lesson=addManualLesson(state,{methodId:document.getElementById('llMethod').value||null,programmeId:document.getElementById('llProg').value||null,rootCause:document.getElementById('llRoot').value,testRunId:document.getElementById('llRun').value||null,title:document.getElementById('llTitle').value.trim(),lesson:document.getElementById('llText').value.trim(),actor:state.settings.actor});state.audit.push(audit('Lesson learned logged',lesson.id,'',lesson.title));await persist();closeModal();render();toast(`${lesson.id} saved and available to future programme planning.`)}}

function editEscalationModal(id){const r=state.escalationRules.find(x=>x.id===id);if(!r)return;openModal(`<h2>${r.id} · ${r.severity} Escalation Rule</h2><div class="modal-grid"><div class="field"><label>Acknowledgement SLA (minutes)</label><input id="erSla" type="number" min="1" value="${r.slaMinutes}"></div><div class="field"><label>Default delay hours</label><input id="erDelay" type="number" min="0" value="${r.defaultDelayHours||0}"></div><div class="field"><label>Replan scope</label><select id="erScope">${['None','Programme','Portfolio'].map(x=>`<option ${x===r.replanScope?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>Notification roles (comma separated)</label><input id="erRoles" value="${esc(r.notifyRoles.join(', '))}"></div></div><label class="review-check"><input id="erIssue" type="checkbox" ${r.createIssue?'checked':''}><span><strong>Create / link issue</strong></span></label><label class="review-check"><input id="erCreateDelay" type="checkbox" ${r.createDelay?'checked':''}><span><strong>Create planning delay constraint</strong></span></label><label class="review-check"><input id="erBlock" type="checkbox" ${r.blockTest?'checked':''}><span><strong>Block affected test until disposition</strong></span></label><button id="saveEscalation" class="btn primary">Save Escalation Rule</button>`);document.getElementById('saveEscalation').onclick=async()=>{const old=JSON.stringify(r);r.slaMinutes=Math.max(1,Number(document.getElementById('erSla').value)||60);r.defaultDelayHours=Math.max(0,Number(document.getElementById('erDelay').value)||0);r.replanScope=document.getElementById('erScope').value;r.notifyRoles=document.getElementById('erRoles').value.split(',').map(x=>x.trim()).filter(Boolean);r.createIssue=document.getElementById('erIssue').checked;r.createDelay=document.getElementById('erCreateDelay').checked;r.blockTest=document.getElementById('erBlock').checked;state.audit.push(audit('Escalation rule changed',r.id,old,JSON.stringify(r)));await persist();closeModal();render();toast(`${r.severity} escalation updated.`)}}

function showKpiDrill(id){const vd=filteredDashboardData(),K=kpis(vd),p=periodRange(),PM=periodMetrics(vd,p.start,p.end),E=efficiencyMetrics(vd,p.start,p.end),IA=issueAnalytics(vd,p.start,p.end);let title=id,body='';if(id==='delivery'){title='Portfolio delivery drill-down';const rows=vd.programmes.slice().sort((a,b)=>new Date(a.dueDate)-new Date(b.dueDate));body=`<div class="callout"><strong>${K.onTimePct}% delivery performance</strong><p>Programme-level forecast, priority and risk behind the portfolio tile.</p></div><div class="table-wrap"><table><thead><tr><th>Programme</th><th>Priority</th><th>Due</th><th>Forecast</th><th>Risk</th><th>Action</th></tr></thead><tbody>${rows.map(x=>`<tr><td><button class="link-button" data-entity="programme" data-id="${x.id}">${x.id} · ${esc(x.project)}</button></td><td>${pill(x.priority)}</td><td>${fmtDate(x.dueDate)}</td><td>${fmtDate(x.forecastCompletion)}</td><td>${pill(x.scheduleRisk)}</td><td><button class="btn small" data-route-jump="planning">Plan</button></td></tr>`).join('')}</tbody></table></div>`}else if(id==='assurance'){title='Validation assurance drill-down';const rows=vd.requirements.filter(r=>r.status!=='Verified').slice().sort((a,b)=>(b.criticality==='Critical')-(a.criticality==='Critical'));body=`<div class="callout"><strong>${K.reqVerified}% requirements verified</strong><p>${K.criticalOutstanding} critical requirements remain outstanding.</p></div><div class="table-wrap"><table><thead><tr><th>Requirement</th><th>Criticality</th><th>Status</th><th>Acceptance</th><th>Coverage</th></tr></thead><tbody>${rows.map(r=>`<tr><td><button class="link-button" data-entity="requirement" data-id="${r.id}">${r.id}</button><div class="small muted">${esc(r.text)}</div></td><td>${pill(r.criticality)}</td><td>${pill(r.status)}</td><td>${esc(r.acceptanceCriterion||'—')}</td><td>${(r.testLegIds||[]).length} leg(s)</td></tr>`).join('')}</tbody></table></div>`}else if(id==='productive'){title='Productive test-time drill-down';const rows=vd.methods.map(m=>({m,t:methodTimeMetrics(vd,m.id)})).filter(x=>x.t.runs).sort((a,b)=>a.t.productivePct-b.t.productivePct).slice(0,20);body=`<div class="callout"><strong>${E.productiveTestPct}% productive test time</strong><p>Direct exposure/execution divided by the complete cycle including queue/waiting.</p></div><div class="table-wrap"><table><thead><tr><th>Method</th><th>Productive</th><th>Queue</th><th>Setup</th><th>FTR</th><th>Learned total</th></tr></thead><tbody>${rows.map(({m,t})=>`<tr><td><button class="link-button" data-entity="method" data-id="${m.id}">${m.id} · ${esc(m.name)}</button></td><td>${t.productivePct}%</td><td>${t.queuePct}%</td><td>${t.setupPct}%</td><td>${t.firstTimeRightPct}%</td><td>${t.learned.total}h</td></tr>`).join('')}</tbody></table></div>`}else if(id==='live'){title='Live anomalies & escalation drill-down';const es=escalationSummary(state);body=`<div class="detail-grid"><div class="detail"><small>Open live alerts</small><strong>${state.liveAlerts.filter(a=>a.status==='Open').length}</strong></div><div class="detail"><small>Open escalation events</small><strong>${es.open}</strong></div><div class="detail"><small>Overdue acknowledgements</small><strong>${es.overdue}</strong></div><div class="detail"><small>Planning-impact events</small><strong>${es.planImpact}</strong></div></div><div class="actions"><button class="btn primary" data-route-jump="live">Open Live Monitor</button><button class="btn" data-route-jump="control">Open Escalation Center</button></div><div class="list">${es.events.slice(0,12).map(e=>`<div class="list-row"><div><strong>${e.id} · ${esc(e.title)}</strong><small>${e.programmeId||'—'} · ${e.legId||'—'} · acknowledge by ${fmtDate(e.requiredAckBy,true)}</small></div>${pill(e.severity)}</div>`).join('')||'<div class="empty">No open escalation events.</div>'}</div>`}else if(id==='finance'){title='Financial control drill-down';const pc=portfolioCost(vd);body=`<div class="detail-grid"><div class="detail"><small>Forecast at completion</small><strong>${currency(vd,pc.totalForecast,true)}</strong></div><div class="detail"><small>Portfolio budget</small><strong>${currency(vd,pc.totalBudget,true)}</strong></div><div class="detail"><small>Variance</small><strong>${currency(vd,pc.variance,true)}</strong></div></div><div class="table-wrap"><table><thead><tr><th>Programme</th><th>Budget</th><th>Forecast</th><th>Variance</th><th>Action</th></tr></thead><tbody>${pc.programmes.slice().sort((a,b)=>b.variance-a.variance).map(x=>`<tr><td>${x.programme.id} · ${esc(x.programme.project)}</td><td>${currency(vd,x.budget,true)}</td><td>${currency(vd,x.forecast,true)}</td><td>${currency(vd,x.variance,true)}</td><td><button class="btn small" data-route-jump="costs">Open</button></td></tr>`).join('')}</tbody></table></div>`}else if(id==='capacity'){title='12-week capacity constraint drill-down';const C=capacityForecast(state,12,state.settings.pipelineMode||'weighted');body=`<div class="callout"><strong>${C.equipmentGapWeeks} equipment-gap weeks · ${C.staffGapWeeks} staffing-gap weeks</strong><p>Committed demand plus probability-weighted potential-project demand.</p></div><h3>Equipment</h3>${gapTable(C.equipment,'equipment')}<h3>Skills / staffing</h3>${gapTable(C.staff,'staff')}<div class="actions"><button class="btn primary" data-route-jump="capacity">Open Capacity Plan</button></div>`}else if(id==='ftr'){title='First-time-right drivers';const rows=PM.runs.slice().sort((a,b)=>String(a.outcome).localeCompare(String(b.outcome)));body=`<div class="callout"><strong>${E.firstTimeRightPct}% first-time-right</strong><p>PASS without rework across the selected KPI period.</p></div><div class="table-wrap"><table><thead><tr><th>Run</th><th>Method</th><th>Outcome</th><th>Programme</th><th>Actual h</th><th>Issues</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${r.id}</td><td>${r.methodId}</td><td>${pill(r.outcome)}</td><td>${r.programmeId}</td><td>${r.actualHours||0}</td><td>${state.issues.filter(i=>i.testRunId===r.id).length}</td></tr>`).join('')}</tbody></table></div>`}else if(['queue','setup','automation','development','hands-on','rework'].includes(id)){title=`${id[0].toUpperCase()+id.slice(1)} efficiency drivers`;const rows=state.methods.map(m=>({m,t:methodTimeMetrics(state,m.id)})).filter(x=>x.t.runs).sort((a,b)=>id==='queue'?b.t.queuePct-a.t.queuePct:id==='setup'?b.t.setupPct-a.t.setupPct:id==='rework'?b.t.reworkPct-a.t.reworkPct:a.t.productivePct-b.t.productivePct).slice(0,20);body=`<div class="detail-grid"><div class="detail"><small>Productive</small><strong>${E.productiveTestPct}%</strong></div><div class="detail"><small>Queue loss</small><strong>${E.queueLossPct}%</strong></div><div class="detail"><small>Setup</small><strong>${E.setupPct}%</strong></div><div class="detail"><small>Automation</small><strong>${E.automationLeveragePct}%</strong></div></div><div class="table-wrap"><table><thead><tr><th>Method</th><th>Runs</th><th>Productive</th><th>Queue</th><th>Setup</th><th>FTR</th><th>Learned time</th></tr></thead><tbody>${rows.map(({m,t})=>`<tr><td><button class="link-button" data-entity="method" data-id="${m.id}">${m.id} · ${esc(m.name)}</button></td><td>${t.runs}</td><td>${t.productivePct}%</td><td>${t.queuePct}%</td><td>${t.setupPct}%</td><td>${t.firstTimeRightPct}%</td><td>${t.learned.total}h</td></tr>`).join('')}</tbody></table></div>`}else if(id==='issues'){title='Issue impact & root causes';body=`${rootCauseDonut(IA.rootCauses)}<div class="table-wrap"><table><thead><tr><th>Issue</th><th>Cause</th><th>Programme / leg</th><th>Severity</th><th>Delay</th><th>Lesson</th></tr></thead><tbody>${PM.periodIssues.slice().sort((a,b)=>(b.delayHours||0)-(a.delayHours||0)).map(i=>`<tr><td>${i.id} · ${esc(i.issueType)}</td><td>${esc(i.rootCause)}</td><td>${i.programmeId} · ${i.legId||'—'}</td><td>${pill(i.severity)}</td><td>${i.delayHours||0}h</td><td>${esc(i.lesson||'—')}</td></tr>`).join('')}</tbody></table></div>`}else if(id==='audit'){title='Audit readiness drivers';const AP=auditPortfolio(state);body=`<div class="callout"><strong>${AP.avg}% average readiness</strong><p>${AP.open} open findings · ${AP.major} major · ${AP.minor} minor.</p></div><div class="list">${AP.rows.map(a=>`<div class="list-row"><div><strong>${a.id} · ${esc(a.name)}</strong><small>${a.standard} · ${a.metrics.completion}% assessed</small></div><div>${pill(`${a.metrics.score}%`)}</div></div>`).join('')}</div>`}else if(id==='service'){title='Calibration + maintenance synergy';const syn=serviceSynergy(state,120);body=`<div class="list">${syn.map(x=>`<div class="list-row"><div><strong>${x.equipmentId} · ${esc(x.name)}</strong><small>Maintenance ${fmtDate(x.maintenanceDue)} · calibration ${fmtDate(x.calibrationDue)} · ${x.proposal}</small></div><strong>${x.combine?`${x.avoidedDowntimeHours}h avoidable`:'Separate'}</strong></div>`).join('')}</div>`}else if(['events','escalations','delays','lessons','lesson-impact'].includes(id)){title='Operational exceptions & learning';const H=workflowHealth(state);body=`<div class="detail-grid"><div class="detail"><small>Open events</small><strong>${H.open}</strong></div><div class="detail"><small>Overdue</small><strong>${H.overdue}</strong></div><div class="detail"><small>Active delays</small><strong>${H.activeDelays}</strong></div><div class="detail"><small>Automatic lessons</small><strong>${H.automaticLessons}</strong></div></div><div class="actions"><button class="btn primary" data-route-jump="control">Open Exceptions & Escalation</button></div>`}else{title='KPI drill-down';body='<div class="empty">No additional drill-down configured.</div>'}openModal(`<h2>${title}</h2>${body}`);wireEntities(modalBody);for(const b of modalBody.querySelectorAll('[data-route-jump]'))b.onclick=()=>{closeModal();go(b.dataset.routeJump)}}

async function handleAction(e){const b=e.currentTarget,a=b.dataset.act,id=b.dataset.id;if(a==='replan'||a==='update-plan')return replan();if(a==='plan-programme')return replanProgramme(id);if(a==='test-detail')return testPortfolioDetail(id);if(a==='portfolio-add-to-builder')return addPortfolioTestToBuilder(id);if(a==='program-builder-edit')return useKnowledgeTemplate(id);if(a==='open-program-execution'){state.settings.executionProgramme=id;await persist();return go('execution');}if(a==='prototype-new')return newPrototypeModal();if(a==='prototype-detail')return prototypeDetailModal(id);if(a==='prototype-complete')return completePrototypeModal(id);if(a==='prototype-replan'){const before=state.prototypeBookings.map(x=>({...x})),o=schedulePrototypeBuilds(state),r=scheduleAll(state);state=r.data;lastPlanDiagnostics=r.diagnostics;state.audit.push(audit('Prototype builds auto-planned','Prototype Portfolio',before.length,`${o.moved.length} build changes`));await persist();render();return toast(`${o.moved.length} prototype booking(s) moved; laboratory plan refreshed.`)}if(a==='kpi-drill')return showKpiDrill(id);if(a==='ack-event')return ackOperationalEvent(id);if(a==='edit-escalation')return editEscalationModal(id);if(a==='lesson-detail')return showLessonDetail(id);if(a==='log-lesson')return logLessonModal(b.dataset.method||id||'');if(a==='scenario')return go('admin');if(a==='reset-scenario')return resetScenario();if(a==='readiness')return showReadiness(id);if(a==='export-json')return exportJSON();if(a==='import-json')return document.getElementById('importFile').click();if(a==='reset-demo')return resetDemo();if(a==='verify')return verifyUI();if(a==='export-req-csv')return exportCSV('requirements');if(a==='export-equipment-csv')return exportCSV('equipment');if(a==='export-cal-csv')return exportCSV('calibrations');if(a==='export-plan-csv')return exportCSV('plan');if(a==='export-kpi-csv')return exportCSV('kpis');if(a==='save-actor'){const v=document.getElementById('actorInput').value.trim()||'Demo Lab Manager';state.audit.push(audit('Demo actor changed','Settings',state.settings.actor,v));state.settings.actor=v;await persist();render();return}if(a==='save-warnings'){const v=document.getElementById('calWarn').value.split(',').map(x=>parseInt(x.trim())).filter(x=>Number.isFinite(x)&&x>0).sort((a,b)=>b-a);if(!v.length)return toast('Enter at least one positive warning threshold.');state.settings.calibrationWarningDays=v;state.audit.push(audit('Calibration warning thresholds changed','Settings','',v.join(',')));await persist();render();return}if(a==='apply-scenario')return applyScenario();if(a==='apply-priority-scenario')return applyPriorityScenario(b.dataset.strategy);if(a==='add-calibration')return addCalibrationModal();if(a==='request-new-test')return requestNewTestModal();if(a==='record-result')return recordResultModal(id);if(a==='report-issue')return reportIssueModal(b.dataset.programme||'',b.dataset.leg||'');if(a==='log-delay')return reportIssueModal(b.dataset.programme||'',id||'');if(a==='resolve-disruption')return resolveDisruption(id);if(a==='upload-spec')return uploadSpecModal();if(a==='open-spec'){const sp=state.specifications.find(x=>x.id===id);return sp?openSpecificationDocument(sp):null;}if(a==='review-spec')return openSpecReviewModal(id);if(a==='impact-spec')return showSpecImpact(id);if(a==='add-requirement')return addRequirementModal();if(a==='cover-requirement')return coverRequirementModal(id);if(a==='jump-builder')return go('builder');if(a==='open-project-plan'){state.settings.planningProject=id;await persist();return go('planning');}if(a==='project-controls')return projectControlsModal(id);if(a==='edit-project-leg')return editProjectLegModal(id);if(a==='cost-settings')return costSettingsModal();if(a==='edit-cost-budget')return editCostBudgetModal(id);if(a==='cost-programme'){state.settings.costProgramme=id;await persist();return render();}if(a==='export-cost-csv')return exportCSV('costs');if(a==='builder-template')return applyBuilderTemplate(id);if(a==='builder-reset')return resetBuilder();if(a==='builder-add-custom')return builderAddCustom();if(a==='builder-remove-custom')return builderRemoveCustom(id);if(a==='builder-create-draft')return createBuilderProgramme(false);if(a==='builder-create-plan')return createBuilderProgramme(true);if(a==='jump-capacity')return go('capacity');if(a==='add-opportunity')return addOpportunityModal();if(a==='edit-opportunity')return addOpportunityModal(id);if(a==='convert-opportunity')return convertOpportunity(id);if(a==='optimize-maintenance'){const o=optimizeMaintenancePlan(state,90);const r=scheduleAll(o.data);state=r.data;lastPlanDiagnostics=r.diagnostics;state.audit.push(audit('Maintenance plan optimized','Equipment', '', `${o.planned} planned · ${o.avoided} conflicts avoided`));await persist();render();return toast(`Maintenance optimized: ${o.planned} new windows, ${o.avoided} booking conflicts avoided, ${r.diagnostics.moved.length} plan changes.`)}if(a==='edit-maint-policy')return editMaintenancePolicyModal(id);if(a==='add-maintenance')return addMaintenanceModal();if(a==='audit-auto'){const m=autoAssessAudit(state,id);state.audit.push(audit('Audit evidence assessment completed',id,'',`${m.score}% readiness`));await persist();render();return toast(`${id} assessed at ${m.score}% readiness.`)}if(a==='new-audit'){const x=createAudit(state,state.settings.auditStandard||'ISO17025');state.settings.auditRecord=x.id;await persist();render();return toast(`${x.id} created.`)}if(a==='audit-item')return auditItemModal(b.dataset.audit,b.dataset.item);if(a==='export-audit-csv')return exportCSV('audit',id);if(a==='export-capacity-csv')return exportCSV('capacity');if(a==='export-maintenance-csv')return exportCSV('maintenance');if(a==='builder-add-method')return builderAddMethod(id);if(a==='builder-deps')return builderDependencyModal(id);if(a==='builder-add-after')return builderAddAfterModal(id,b.dataset.mode||'sequential');if(a==='builder-remove-leg')return builderRemoveLeg(id);if(a==='builder-move-up')return builderMoveLeg(id,-1);if(a==='builder-move-down')return builderMoveLeg(id,1);if(a==='lesson-provenance')return showLessonProvenance(id);if(a==='edit-method-cost')return editMethodCostModal(id);if(a==='log-leg-time')return logLegTimeModal(id);if(a==='log-method-time')return logMethodTimeModal(id);if(a==='log-development-time')return logDevelopmentTimeModal(id);if(a==='apply-learned-standard')return applyLearnedStandard(id);if(a==='open-live-session'){state.settings.liveSession=id;await persist();return go('live')}if(a==='toggle-live')return toggleLive(id);if(a==='inject-anomaly')return injectAnomaly(id);if(a==='ack-alert')return ackAlert(id);if(a==='configure-alerts')return configureAlertsModal(id);if(a==='connect-live')return connectLiveModal(id);if(a==='import-live-csv')return importLiveDataModal(id);if(a==='auto-report')return autoReportModal(id);if(a==='recommendation-action')return recommendationAction(id);if(a==='new-quality')return newQualityModal();if(a==='quality-from-issues')return captureRecentIssues();if(a==='quality-capture-issue'){const q=qualityEventFromIssue(state,id);if(q){state.settings.planDirty=true;state.audit.push(audit('Issue promoted to quality event',id,'',q.id));await persist();render();toast(`${q.id} created from ${id}.`)}return}if(a==='quality-detail')return qualityDetailModal(id);if(a==='quality-advance')return advanceQualityEvent(id);if(a==='quality-add-capa')return qualityCapaModal(id);if(a==='quality-edit')return qualityEditModal(id);if(a==='capa-verify')return verifyCapa(id);if(a==='custody-detail')return custodyDetailModal(id);if(a==='custody-move')return custodyMoveModal(id);if(a==='custody-move-batch')return custodyBatchModal();if(a==='custody-split-group')return custodySplitModal(id);if(a==='custody-merge-groups')return custodyMergeModal();if(a==='custody-scan'){const d=state.duts[Math.floor(Math.random()*state.duts.length)];return custodyDetailModal(d.id)}if(a==='guided-start-select')return guidedStartSelectModal();if(a==='guided-start')return startGuidedForLeg(id);if(a==='guided-open')return guidedOpenModal(id);if(a==='guided-step')return guidedStepModal(id,b.dataset.step);if(a==='guided-review')return guidedReviewModal(id);if(a==='twin-settings')return twinSettingsModal();if(a==='twin-run'){render();return toast('Planning digital twin recalculated from current operational state.')}if(a==='new-msa')return msaModal();if(a==='new-uncertainty')return newUncertaintyModal();if(a==='metrology-impact')return metrologyImpactModal(id);if(a==='materials-export')return exportInventoryCSV();if(a==='new-inventory-item')return newInventoryModal();if(a==='inventory-adjust')return inventoryAdjustModal(id);if(a==='material-leg-detail')return materialLegModal(id);if(a==='new-external-lab')return newExternalLabModal();if(a==='external-candidate')return toast('Outsourcing candidates are ranked below from current internal demand and approved supplier scope.');if(a==='external-options')return externalOptionsModal(id);if(a==='external-commit')return commitExternal(id,b.dataset.lab);if(a==='knowledge-use')return useKnowledgeTemplate(id);if(a==='jump-live')return go('live');}


async function ackOperationalEvent(id){if(!acknowledgeOperationalEvent(state,id,state.settings.actor))return toast('Event not found.');state.audit.push(audit('Operational escalation acknowledged',id,'Open','Acknowledged'));await persist();render();toast(`${id} acknowledged.`)}
async function replanProgramme(programmeId){if(!programmeId)return replan();const before=capturePlanningSnapshot(state,`Before ${programmeId} replan`),r=scheduleProgramme(state,programmeId);state=r.data;state.settings.planDirty=false;lastPlanDiagnostics=r.diagnostics;recomputeRequirementStatuses(state);const diff=planningDiff(before,state,{programmeId});state.settings.lastProgrammePlanDiff={programmeId,timestamp:new Date().toISOString(),rows:diff};await persist();render();toast(`${programmeId} replanned: ${diff.length} booking change(s); other programme bookings preserved.`);showPlanningDiff(programmeId,diff)}
function showPlanningDiff(programmeId,rows=null){rows=rows||state.settings.lastProgrammePlanDiff?.rows||[];openModal(`<h2>${programmeId} · Replan Impact</h2><div class="callout"><strong>${rows.length} booking change(s)</strong><p>Programme-only planning preserves existing bookings from other programmes and rebuilds this programme around current constraints.</p></div><div class="table-wrap"><table><thead><tr><th>Leg</th><th>Change</th><th>Old start</th><th>New start</th><th>Equipment</th><th>Staff</th></tr></thead><tbody>${rows.map(x=>`<tr><td>${x.legId}</td><td>${x.type}</td><td>${fmtDate(x.oldStart,true)}</td><td>${fmtDate(x.newStart,true)}</td><td>${x.oldEquipment||'—'} → ${x.newEquipment||'—'}</td><td>${x.oldStaff||'—'} → ${x.newStaff||'—'}</td></tr>`).join('')||'<tr><td colspan="6" class="empty">No booking movement was required.</td></tr>'}</tbody></table></div>`)}

async function replan(){const before=capturePlanningSnapshot(state,'Before portfolio replan'),r=scheduleAll(state);state=r.data;state.settings.planDirty=false;lastPlanDiagnostics=r.diagnostics;recomputeRequirementStatuses(state);const diff=planningDiff(before,state);state.settings.lastPortfolioPlanDiff={timestamp:new Date().toISOString(),rows:diff};await persist();render();toast(`Portfolio plan updated: ${diff.length} booking changes, ${r.diagnostics.unscheduled.length} unscheduled.`)}
async function changePriority(id,val){state=applyPriority(state,id,val);const r=scheduleAll(state);state=r.data;state.settings.planDirty=false;lastPlanDiagnostics=r.diagnostics;await persist();render();toast(`${id} set to ${val}; ${r.diagnostics.moved.length} bookings moved.`)}
function updateScenarioTargets(){const t=document.getElementById('scenarioType'),sel=document.getElementById('scenarioTarget');if(!t||!sel)return;if(t.value==='staff_unavailable')sel.innerHTML=state.staff.map(s=>`<option value="${s.id}">${s.id} · ${esc(s.name)}</option>`).join('');else if(t.value==='add_equipment')sel.innerHTML=[...new Set(state.equipment.map(e=>e.type))].sort().map(x=>`<option value="${esc(x)}">${esc(x)}</option>`).join('');else sel.innerHTML=state.equipment.map(e=>`<option value="${e.id}">${e.id} · ${esc(e.name)}</option>`).join('')}
async function applyScenario(){const type=document.getElementById('scenarioType').value,target=document.getElementById('scenarioTarget').value;let sc;if(type==='equipment_unavailable')sc={type,equipmentId:target,start:dayISO(0,8),end:dayISO(7,17),label:`${target} unavailable for 7 days`};else if(type==='staff_unavailable')sc={type,staffId:target,start:dayISO(3,8),end:dayISO(10,17),label:`${state.staff.find(s=>s.id===target)?.name} unavailable next week`};else sc={type,equipmentType:target,label:`Add temporary ${target}`};state.settings.scenario=sc;state.audit.push(audit('Scenario applied','Planning','',sc.label));const r=scheduleAll(state,{scenario:sc});state=r.data;lastPlanDiagnostics=r.diagnostics;await persist();render();toast(`Scenario applied; ${r.diagnostics.moved.length} bookings moved.`)}
async function resetScenario(){state.settings.scenario=null;state.audit.push(audit('Scenario reset','Planning','active','baseline'));const r=scheduleAll(state,{scenario:null});state=r.data;lastPlanDiagnostics=r.diagnostics;await persist();render();toast('Scenario reset and baseline schedule recalculated.');}

function showEntity(type,id){if(type==='requirement')return showRequirement(id);if(type==='specification')return showSpecification(id);if(type==='programme')return showProgramme(id);if(type==='leg')return showLeg(id);if(type==='dut')return showDut(id);if(type==='equipment')return showEquipmentDetail(id);if(type==='method')return showMethod(id);if(type==='staff')return showStaff(id);if(type==='prototype')return prototypeDetailModal(id)}
function showRequirement(id){const r=state.requirements.find(x=>x.id===id);if(!r)return;const o=requirementOps(r),results=o.results,methods=o.methods.length?o.methods:[o.suggested].filter(Boolean);openModal(`<h2>${r.id} · Requirement Decision & Traceability</h2><div class="callout"><strong>${esc(r.text)}</strong><div class="small">Acceptance criterion: ${esc(r.acceptanceCriterion)}</div></div><div class="trace"><div class="trace-step"><small>Source</small><strong>${r.sourceId}</strong></div><div class="trace-step"><small>Controlled spec</small><strong>${o.sp?`${o.sp.id} Rev ${o.sp.revision}`:'No spec'}</strong></div><div class="trace-step"><small>Validation requirement</small><strong>${r.id}</strong></div><div class="trace-step"><small>Coverage method</small><strong>${methods.map(m=>m.id).join(', ')||'Gap'}</strong></div><div class="trace-step"><small>Test legs</small><strong>${o.legs.map(l=>l.id).join(', ')||'Not covered'}</strong></div><div class="trace-step"><small>DUTs</small><strong>${new Set(o.legs.flatMap(l=>l.dutIds)).size} assigned</strong></div><div class="trace-step"><small>Evidence</small><strong>${results.length} results</strong></div><div class="trace-step"><small>Status</small><strong>${r.status}</strong></div></div><div class="grid kpi compact-kpis">${kpiCard('Criticality',r.criticality,r.category)}${kpiCard('Operational action',o.action,'Next control step')}${kpiCard('Forecast coverage cost',currency(state,o.estimatedCost,true),o.legs.length?'linked legs':'indicative suggested method')}${kpiCard('Method state',methods[0]?(methods[0].active?'Exists / Released':'Needs Development'):'No method','Test Library readiness')}</div>${o.sp?`<div class="callout ${o.sp.status==='Released'?'':'warning'}"><strong>Specification basis:</strong> ${o.sp.id} Rev ${esc(o.sp.revision)} · ${o.sp.status} · quality ${o.sp.qualityScore}%. ${o.sp.status!=='Released'?'Future execution remains gated until a released basis exists.':''}</div>`:''}<h3>Coverage legs</h3><div class="table-wrap"><table><thead><tr><th>Leg</th><th>Method</th><th>DUTs</th><th>Planned</th><th>Resources</th><th>Cost</th><th>Status</th></tr></thead><tbody>${o.legs.map(l=>{const C=estimateLegCost(state,l),m=state.methods.find(x=>x.id===l.methodId);return`<tr><td><span class="link mono" data-entity="leg" data-id="${l.id}">${l.id}</span></td><td>${m?.id} · ${esc(m?.name||'')}</td><td>${l.dutIds.length}</td><td>${fmtDate(l.plannedStart,true)}</td><td>${l.equipmentId||'—'} / ${state.staff.find(s=>s.id===l.staffId)?.name||'—'}</td><td>${currency(state,C.total,true)}</td><td>${pill(l.status)}</td></tr>`}).join('')||'<tr><td colspan="7" class="empty">No coverage has been created.</td></tr>'}</tbody></table></div>${results.length?`<h3>Objective evidence</h3><div class="table-wrap"><table><thead><tr><th>Result</th><th>DUT</th><th>Parameter</th><th>Value</th><th>Status</th><th>Evidence</th></tr></thead><tbody>${results.slice(0,25).map(x=>`<tr><td>${x.id}</td><td>${x.dutId}</td><td>${esc(x.parameter)}</td><td>${esc(x.value)} ${esc(x.unit||'')}</td><td>${pill(x.status)}</td><td>${x.evidenceId||'—'}</td></tr>`).join('')}</tbody></table></div>`:''}<div class="actions" style="margin-top:14px"><button id="manageReqCoverage" class="btn primary">${o.legs.length?'Manage / Add Coverage':'Create Test Coverage'}</button>${o.sp?`<button id="openReqSpec" class="btn">Open Specification</button>`:''}</div>`);wireEntities(modalBody);document.getElementById('manageReqCoverage').onclick=()=>coverRequirementModal(id);if(o.sp)document.getElementById('openReqSpec').onclick=()=>showSpecification(o.sp.id)}

function showProgramme(id){const p=state.programmes.find(x=>x.id===id),ls=state.legs.filter(l=>l.programmeId===id),req=state.requirements.filter(r=>r.programmeId===id),duts=state.duts.filter(d=>d.programmeId===id),spec=state.specifications?.find(s=>s.programmeId===id);if(!p)return;const C=programmeCost(state,id),R=programmeReadiness(id),newMethods=ls.filter(l=>!state.methods.find(m=>m.id===l.methodId)?.active),issues=(state.issues||[]).filter(i=>i.programmeId===id);openModal(`<h2>${p.id} · ${esc(p.project)}</h2><div class="detail-grid"><div class="detail"><small>Customer</small><strong>${esc(p.customer)}</strong></div><div class="detail"><small>Product</small><strong>${esc(p.product)} ${p.productRevision}</strong></div><div class="detail"><small>Priority / Risk</small><strong>${p.priority} · ${p.scheduleRisk}</strong></div><div class="detail"><small>Programme gate</small><strong>${p.gateStatus||'Released'}</strong></div><div class="detail"><small>Due / Forecast</small><strong>${fmtDate(p.dueDate)} → ${fmtDate(p.forecastCompletion)}</strong></div><div class="detail"><small>Owner</small><strong>${esc(p.owner)}</strong></div><div class="detail"><small>Specification</small><strong>${spec?`${spec.id} Rev ${spec.revision} · ${spec.status}`:'—'}</strong></div><div class="detail"><small>Release readiness</small><strong>${R.score}%</strong></div></div><h3>Cost position</h3><div class="grid kpi compact-kpis">${kpiCard('Estimated',currency(state,C.estimated.total,true),'Baseline programme cost')}${kpiCard('Actual to date',currency(state,C.actualToDate,true),'Completed execution')}${kpiCard('Forecast at completion',currency(state,C.forecast,true),`budget ${currency(state,C.budget,true)}`)}${kpiCard('Budget variance',`${C.variance>=0?'+':''}${currency(state,C.variance,true)}`,`${C.variancePct>=0?'+':''}${C.variancePct}%`)}</div><div class="callout warning"><strong>Demo storyline:</strong> ${esc(p.storyline)}</div><h3>Release readiness</h3>${R.checks.map(x=>`<div class="checkline"><span class="${x.ok?'diag-pass':'diag-fail'}">${x.ok?'PASS':'CHECK'}</span><strong>${esc(x.name)}</strong><span class="small muted">${esc(x.detail)}</span></div>`).join('')}<h3>Test programme legs</h3><div class="tree">${ls.map(l=>{const m=state.methods.find(x=>x.id===l.methodId),lc=estimateLegCost(state,l);return `<div class="tree-item"><span>${l.sequence}</span><strong class="link" data-entity="leg" data-id="${l.id}">${l.id}</strong><span>${esc(l.name)}</span><span class="small muted">${m?.active?'Existing':'Develop'} · ${currency(state,lc.total,true)}</span>${pill(l.status)}</div>`}).join('')}</div><h3>Coverage & operating history</h3><p class="small">${req.length} requirements · ${duts.length} DUTs · ${req.filter(r=>r.status==='Verified').length} verified · ${req.filter(r=>r.status==='Failed').length} failed · ${newMethods.length} legs use unreleased methods · ${issues.length} recorded issues.</p>`) }
